const STORAGE_KEY='bilalSmartLibraryCloudV06';
const LEGACY_KEYS=[];
const VERSION='0.6.8';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const deepClone=x=>JSON.parse(JSON.stringify(x));
const esc=v=>String(v??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));

const defaults={
  config:{siteName:'Bilal Smart Library',schoolName:'مدرسة بلال بن رباح النموذجية للبنين',logo:'',maxBooks:3,loanDays:14,renewals:1,preventOverdue:true,reservationDays:3,kioskName:'محطة الاستعارة 01',kioskLocation:'مركز مصادر التعلّم',currentStationId:'KIOSK-01',autoClose:true,sessionSeconds:12,successSound:true,readerMode:'hybrid',allowPersonalIdScan:false},
  students:[],
  books:[],
  loans:[], reservations:[],
  users:[],
  stations:[{id:'KIOSK-01',name:'محطة الاستعارة الذاتية 1',location:'مركز مصادر التعلّم',type:'self_checkout',readerMode:'hybrid',enabled:true}],
  activityLogs:[], meta:{revision:1,updatedAt:null}
};

let state=loadState();
let currentView='dashboard', pendingLogoData=state.config.logo||'', currentUser=null, kioskTimer=null, kioskDeadline=0, scannerHandler=null;
let remoteMode=false, remoteRevision=0, remotePoller=null, syncTimer=null;
const CLOUD=window.BILAL_CLOUD||{};
const sb=window.supabase?.createClient(CLOUD.url,CLOUD.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
let authUser=null, cloudSyncBusy=false, cloudLastLoad=0;

const pageMeta={
 dashboard:['لوحة القيادة','نظرة تنفيذية شاملة على المكتبة وحركة الاستعارة'], kiosk:['الاستعارة الذاتية','محطة خدمة ذاتية للطلاب بالباركود أو RFID'],
 students:['الطلاب','إدارة الطلاب، السجل الكامل، البطاقات والاستيراد من Excel'], books:['الكتب والنسخ','إدارة النسخ، الملصقات، السجل والاستيراد من Excel'],
 loans:['الاستعارات','متابعة الاستعارات النشطة والتاريخية والتجديد'], circulation:['حركة الاستعارة اليومية','اعرض عمليات الاستعارة والإرجاع لأي تاريخ مع تفاصيل المواعيد'], returns:['الإرجاع السريع','مسح باركود أو RFID للكتاب وإتمام الإرجاع'],
 overdue:['المتأخرات','متابعة الكتب المتأخرة والطلاب المطلوب متابعتهم'], reservations:['الحجوزات','قائمة انتظار الكتب والحجوزات النشطة'],
 reports:['التقارير والإحصائيات','تقارير تشغيلية متقدمة قابلة للتصفية والتصدير'], users:['المستخدمون والصلاحيات','إدارة حسابات المدير وأمناء المكتبة'],
 stations:['الأجهزة والمحطات','إدارة محطات الاستعارة والاستعداد للباركود وRFID'], activity:['سجل العمليات','سجل تدقيق تفصيلي لكل عملية وتعديل'],
 settings:['الإعدادات','الهوية وسياسات الاستعارة والحجز والقارئ والنسخ الاحتياطي']
};
const ROLE_LABELS={admin:'مدير النظام',librarian:'أمين المكتبة',kiosk:'محطة استعارة',viewer:'مشاهدة فقط'};
const ROLE_VIEWS={admin:Object.keys(pageMeta),librarian:['dashboard','kiosk','students','books','loans','circulation','returns','overdue','reservations','reports','activity'],kiosk:['kiosk','returns'],viewer:['dashboard','students','books','loans','circulation','overdue','reservations','reports']};

function loadState(){
  let saved=null;
  try{saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')}catch(e){}
  if(!saved){for(const k of LEGACY_KEYS){try{saved=JSON.parse(localStorage.getItem(k)||'null');if(saved)break}catch(e){}}}
  const s=saved||deepClone(defaults);
  s.config={...defaults.config,...(s.config||{})};
  for(const key of ['students','books','loans','reservations','users','stations','activityLogs']) s[key]=Array.isArray(s[key])?s[key]:deepClone(defaults[key]);
  if(!s.users.length)s.users=deepClone(defaults.users); if(!s.stations.length)s.stations=deepClone(defaults.stations);
  s.meta={...defaults.meta,...(s.meta||{})};
  s.students=s.students.map(x=>({...x,status:x.status||'نشط',rfidTag:x.rfidTag||''}));
  s.books=s.books.map((x,i)=>({...x,accession:x.accession||`ACC${String(i+1).padStart(6,'0')}`,isbn:x.isbn||'',author:x.author||'',publisher:x.publisher||'',year:x.year||'',rfidTag:x.rfidTag||''}));
  s.loans=s.loans.map(x=>({...x,renewalsUsed:Number(x.renewalsUsed||0),stationId:x.stationId||s.config.currentStationId||'KIOSK-01'}));
  s.kiosk={step:'student',student:null,lastBook:null,lastLoanDueISO:null};
  return s;
}
function persistLocal(){state.meta.revision=Number(state.meta.revision||0)+1;state.meta.updatedAt=nowISO();localStorage.setItem(STORAGE_KEY,JSON.stringify(serializableState()));updateSaveStamp()}
function serializableState(){return {config:state.config,students:state.students,books:state.books,loans:state.loans,reservations:state.reservations,users:state.users,stations:state.stations,activityLogs:state.activityLogs,meta:state.meta}}
function saveState(sync=true){persistLocal();if(remoteMode&&sync&&currentUser&&!['kiosk','viewer'].includes(currentUser.role))scheduleRemotePush()}
function replaceState(x){if(!x)return;state.config={...defaults.config,...(x.config||{})};for(const k of ['students','books','loans','reservations','users','stations','activityLogs'])state[k]=Array.isArray(x[k])?x[k]:[];state.meta={...defaults.meta,...(x.meta||{})};state.kiosk={step:'student',student:null,lastBook:null,lastLoanDueISO:null};pendingLogoData=state.config.logo||'';refreshDerivedState();localStorage.setItem(STORAGE_KEY,JSON.stringify(serializableState()));applyBranding()}
function nowISO(){return new Date().toISOString()}
function todayISO(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function addDaysISO(days,from=new Date()){const d=new Date(from);d.setHours(12,0,0,0);d.setDate(d.getDate()+Number(days||0));return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function formatISODate(iso){if(!iso)return '—';const d=new Date(String(iso).slice(0,10)+'T12:00:00');return Number.isNaN(d.getTime())?iso:new Intl.DateTimeFormat('ar-QA',{year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function formatDateTime(iso){if(!iso)return '—';const d=new Date(iso);return Number.isNaN(d)?iso:new Intl.DateTimeFormat('ar-QA',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(d)}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2700)}
function maskPid(v){const s=String(v||'');return !s?'—':s.length<=4?'••••':`${'•'.repeat(Math.min(7,s.length-4))}${s.slice(-4)}`}
function statusClass(s){return s==='متاح'||s==='نشط'||s==='مكتمل'?'available':s==='مستعار'||s==='محجوز'?'loaned':s==='متأخر'||s==='موقوف'?'overdue':'returned'}
function currentStation(){return state.stations.find(x=>x.id===state.config.currentStationId)||state.stations[0]||{id:'LOCAL',name:'محطة محلية',location:'—',readerMode:'barcode'}}
function stationName(id){return state.stations.find(x=>x.id===id)?.name||id||'—'}
function logActivity(type,message,meta={}){
  state.activityLogs.unshift({id:`LG${Date.now()}${Math.floor(Math.random()*99)}`,type,message,meta,stationId:meta.stationId||currentStation().id,user:currentUser?.username||'kiosk',atISO:nowISO()});state.activityLogs=state.activityLogs.slice(0,2000);
  if(remoteMode&&authUser&&currentUser&&['admin','librarian'].includes(currentUser.role)){
    const st=state.stations.find(x=>x.id===(meta.stationId||currentStation().id));
    const stu=state.students.find(x=>x.code===meta.studentCode); const bk=state.books.find(x=>x.code===meta.bookCode);
    sb.from('activity_logs').insert({school_id:CLOUD.schoolId,actor_user_id:authUser.id,station_id:st?.dbId||null,student_id:stu?.dbId||null,book_copy_id:bk?.dbCopyId||null,action:type,details:{message,actor_name:currentUser?.displayName||'',...meta}}).then(()=>{}).catch(()=>{});
  }
}
function updateSaveStamp(){if(typeof document==='undefined')return;const el=document.querySelector('.sidebar-footer div');if(el)el.innerHTML=`<span class="dot ok"></span> آخر حفظ: ${new Intl.DateTimeFormat('ar-QA',{hour:'2-digit',minute:'2-digit'}).format(new Date())}`}

function refreshDerivedState(){
  const today=todayISO();
  state.loans.forEach(l=>{l.loanDateISO=(l.loanDateISO||l.createdISO||today).slice(0,10);l.dueDateISO=(l.dueDateISO||addDaysISO(state.config.loanDays,new Date(l.loanDateISO+'T12:00:00'))).slice(0,10);if(l.status==='مستعار'&&l.dueDateISO<today)l.status='متأخر';if(l.status==='متأخر'&&l.dueDateISO>=today)l.status='مستعار'});
  state.students.forEach(s=>s.loans=state.loans.filter(l=>l.studentCode===s.code&&['مستعار','متأخر'].includes(l.status)).length);
  state.books.forEach(b=>{const active=state.loans.some(l=>l.bookCode===b.code&&['مستعار','متأخر'].includes(l.status));if(active)b.status='مستعار';else if(b.status==='مستعار')b.status='متاح'});
  state.reservations.forEach(r=>{if(!r.createdISO)r.createdISO=nowISO();if(r.status==='نشط'&&r.expiresISO&&r.expiresISO<today)r.status='منتهي'});
}
const activeLoans=()=>{refreshDerivedState();return state.loans.filter(l=>['مستعار','متأخر'].includes(l.status))};
const overdueLoans=()=>{refreshDerivedState();return state.loans.filter(l=>l.status==='متأخر')};
const activeReservations=()=>state.reservations.filter(r=>r.status==='نشط');
const todayLoans=()=>state.loans.filter(l=>(l.loanDateISO||'')===todayISO());
const returnedToday=()=>state.loans.filter(l=>(l.returnedDateISO||'')===todayISO());

function allowed(view){if(!currentUser)return view==='kiosk';return (ROLE_VIEWS[currentUser.role]||[]).includes(view)}
function applyPermissions(){$$('.admin-only').forEach(x=>x.style.display=currentUser?.role==='admin'?'flex':'none');const chip=$('#topUserName');if(chip)chip.textContent=currentUser?.displayName||'محطة ذاتية';const role=$('#topUserRole');if(role)role.textContent=currentUser?ROLE_LABELS[currentUser.role]:'وضع الطالب';const av=document.querySelector('#userChip .avatar');if(av)av.textContent=(currentUser?.displayName||'ط')[0]}
function logoMarkup(){return state.config.logo?`<img src="${state.config.logo}" alt="شعار المدرسة" class="brand-logo">`:'<span>م</span>'}
function applyBranding(){document.title=state.config.siteName;$('#loginSiteName').textContent=state.config.siteName;$('#loginSchoolName').textContent=state.config.schoolName;$('#sidebarSiteName').textContent=state.config.siteName;$('#sidebarSchoolName').textContent=state.config.schoolName;$('#loginLogoSlot').innerHTML=logoMarkup();$('#sidebarLogoSlot').innerHTML=logoMarkup();updateModePill()}
function updateModePill(){const el=$('#modePill');if(!el)return;el.innerHTML=`<span class="dot ${remoteMode?'ok':'warn'}"></span> وضع التشغيل <b>${remoteMode?'Supabase Cloud':'غير متصل'}</b>`}
function setPage(view){if(!allowed(view)){view=currentUser?'dashboard':'kiosk'}currentView=view;const [t,s]=pageMeta[view];$('#pageTitle').textContent=t;$('#pageSub').textContent=s;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
function render(view=currentView){refreshDerivedState();setPage(view);const c=$('#content');const fn={dashboard,kiosk,students,books,loans,circulation,returns,overdue,reservations,reports,users,stations,activity,settings}[currentView];c.innerHTML=fn?fn():'';bindDynamic(currentView);updateSidebarBadges();applyPermissions()}
function updateSidebarBadges(){const ob=document.querySelector('[data-view="overdue"] .badge');if(ob)ob.textContent=overdueLoans().length;const rb=document.querySelector('[data-view="reservations"] .reserve-badge');if(rb)rb.textContent=activeReservations().length}

function showApp(){clearKioskTimer();document.body.classList.remove('kiosk-guest');$('#loginView').classList.add('hidden');$('#appView').classList.remove('hidden');applyPermissions();render(currentUser?.role==='kiosk'?'kiosk':'dashboard')}
async function showLogin(){clearKioskTimer();detachGlobalScanner();document.body.classList.remove('kiosk-guest');try{await sb?.auth.signOut()}catch{}currentUser=null;authUser=null;remoteMode=false;clearInterval(remotePoller);$('#appView').classList.add('hidden');$('#loginView').classList.remove('hidden');updateModePill()}
async function attemptLogin(){const email=$('#loginUser').value.trim().toLowerCase(),p=$('#loginPass').value;if(!email||!p){toast('أدخل البريد الإلكتروني وكلمة المرور');return}const btn=$('#loginBtn');btn.disabled=true;btn.textContent='جارٍ الدخول...';const {data,error}=await sb.auth.signInWithPassword({email,password:p});btn.disabled=false;btn.textContent='دخول النظام';if(error||!data.user){toast('بيانات الدخول غير صحيحة');return}authUser=data.user;const ok=await loadCloudState();if(!ok){await sb.auth.signOut();toast('الحساب غير مرتبط بهذه المدرسة أو موقوف');return}remoteMode=true;logActivity('دخول',`تسجيل دخول ${currentUser.displayName}`);showApp();startRemotePolling()}
function openKioskGuest(){toast('سجّل الدخول بحساب أمين المكتبة أو حساب المحطة أولًا، ثم افتح محطة الاستعارة.')}

function dashboard(){
 const active=activeLoans().length, avail=state.books.filter(b=>b.status==='متاح').length, overdue=overdueLoans().length, reservations=activeReservations().length;
 const last7=[...Array(7)].map((_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const iso=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');return {iso,label:new Intl.DateTimeFormat('ar-QA',{weekday:'short'}).format(d),n:state.loans.filter(l=>l.loanDateISO===iso).length}});const max=Math.max(1,...last7.map(x=>x.n));
 const tops=topBooks(5);
 const isAdmin=currentUser?.role==='admin';
 return `<div class="hero"><div><h3>${isAdmin?'مركز تحكم مدير المكتبة':'لوحة أمين المكتبة'} ✨</h3><p><b>${esc(state.config.schoolName)}</b> — ${isAdmin?'إدارة الاستعارة الذاتية، المستخدمين، الأجهزة، السجلات والتقارير من مكان واحد.':'متابعة الاستعارة والإرجاع والحجوزات وخدمة الطلاب اليومية بسرعة.'}</p></div><div class="hero-actions"><button class="btn primary" onclick="render('kiosk')">فتح المحطة</button><button class="btn ghost" onclick="render('${isAdmin?'reports':'returns'}')">${isAdmin?'التقارير':'الإرجاع السريع'}</button></div></div>
 <div class="kpis"><div class="kpi"><small>استعارات اليوم</small><strong>${todayLoans().length}</strong><div class="trend up">${returnedToday().length} إرجاع اليوم</div></div><div class="kpi"><small>مستعار الآن</small><strong>${active}</strong><div class="trend warn">${overdue} متأخر</div></div><div class="kpi"><small>كتب متاحة</small><strong>${avail}</strong><div class="trend up">من ${state.books.length} نسخة</div></div><div class="kpi"><small>حجوزات نشطة</small><strong>${reservations}</strong><div class="trend up">قائمة انتظار</div></div></div>
 <div class="grid-2"><div class="card"><div class="card-head"><h3>حركة الاستعارة — آخر 7 أيام</h3><span>LIVE DATA</span></div><div class="chart-bars">${last7.map(x=>`<div class="bar-wrap"><b>${x.n}</b><div class="bar" style="height:${Math.max(7,(x.n/max)*150)}px"></div><span>${x.label}</span></div>`).join('')}</div></div><div class="card"><div class="card-head"><h3>الأكثر استعارة</h3><span>TOP BOOKS</span></div><div class="mini-list">${tops.length?tops.map((x,i)=>`<div class="mini-row"><div class="rank">${i+1}</div><div><b>${esc(x.title)}</b><span>${esc(x.code)}</span></div><em>${x.count} مرة</em></div>`).join(''):'<div class="empty-state">لا توجد بيانات بعد</div>'}</div></div></div>
 <div class="quick-grid">${isAdmin?`<button class="quick-card" onclick="render('students')"><b>استيراد الطلاب</b><span>Excel / CSV + بطاقات</span></button><button class="quick-card" onclick="render('books')"><b>استيراد الكتب</b><span>Excel / CSV + ملصقات</span></button><button class="quick-card" onclick="render('users')"><b>المستخدمون</b><span>${state.users.filter(x=>x.active).length} حساب نشط</span></button><button class="quick-card" onclick="render('stations')"><b>المحطات</b><span>${state.stations.filter(x=>x.enabled).length} محطة مفعلة</span></button>`:`<button class="quick-card" onclick="render('returns')"><b>الإرجاع السريع</b><span>${returnedToday().length} إرجاع اليوم</span></button><button class="quick-card" onclick="render('loans')"><b>الاستعارات</b><span>${active} نشطة الآن</span></button><button class="quick-card" onclick="render('reservations')"><b>الحجوزات</b><span>${reservations} حجز نشط</span></button><button class="quick-card" onclick="render('overdue')"><b>المتأخرات</b><span>${overdue} تحتاج متابعة</span></button>`}</div>`
}
function topBooks(n=10){const map={};state.loans.forEach(l=>{map[l.bookCode]=(map[l.bookCode]||0)+1});return Object.entries(map).map(([code,count])=>({code,count,title:state.books.find(b=>b.code===code)?.title||state.loans.find(l=>l.bookCode===code)?.book||code})).sort((a,b)=>b.count-a.count).slice(0,n)}
function topStudents(n=10){const map={};state.loans.forEach(l=>{map[l.studentCode]=(map[l.studentCode]||0)+1});return Object.entries(map).map(([code,count])=>({code,count,name:state.students.find(s=>s.code===code)?.name||state.loans.find(l=>l.studentCode===code)?.student||code})).sort((a,b)=>b.count-a.count).slice(0,n)}

function kiosk(){const st=currentStation(),k=state.kiosk,mode=st.readerMode||state.config.readerMode;return `<div class="kiosk-shell"><div class="kiosk-instructions"><div class="kiosk-brand"><div class="brand-mark small logo-slot">${logoMarkup()}</div><div><h3>${esc(state.config.siteName)}</h3><span>${esc(state.config.schoolName)}</span></div></div><span class="scanner-ready">● ${esc(st.name)} — ${mode==='rfid'?'RFID':mode==='hybrid'?'Barcode + RFID':'Barcode'}</span>${!currentUser?'<button class="kiosk-exit" id="exitGuestKiosk">خروج المحطة</button>':''}<h1>${k.student?'امسح الكتاب الآن':'ابدأ ببطاقة الطالب'}</h1><p>${k.student?'مرّر باركود الكتاب أمام القارئ، وسيتم تسجيل الاستعارة تلقائيًا.':'مرّر بطاقة الطالب أمام القارئ، وسيظهر اسم الطالب تلقائيًا ثم يطلب منك مسح الكتاب.'}</p><div class="scan-orb">▥</div><div class="kiosk-hint">مرّر الباركود فقط — لا حاجة للضغط على Enter أو أي زر.</div></div><div class="kiosk-panel kiosk-stage">${k.student?studentKioskCard(k):`<div class="scan-empty"><h2>جاهز للمسح</h2><p>مرّر بطاقة الطالب أمام القارئ</p></div>`}<input id="kioskScan" class="scan-input" autocomplete="off" inputmode="none" readonly aria-label="قارئ الباركود" placeholder="جاهز للمسح التلقائي"/><div class="scan-feedback" id="scanFeedback"></div></div></div>`}
function studentKioskCard(k){const active=state.loans.filter(l=>l.studentCode===k.student.code&&['مستعار','متأخر'].includes(l.status));const activeCount=k.student.activeLoans??active.length;const late=k.student.overdue??active.filter(l=>l.status==='متأخر').length;return `<div class="student-card"><div class="student-head"><div class="student-photo">${esc(k.student.name[0])}</div><div><h3>مرحبًا، ${esc(k.student.name)}</h3><p>${esc(k.student.grade)} / ${esc(k.student.section)} • الكتب الحالية ${activeCount}/${state.config.maxBooks}${late?` • <b class="danger-text">${late} متأخر</b>`:''}</p></div><div class="student-code">${esc(k.student.code)}</div></div>${k.lastBook?`<div class="loan-book"><div class="book-cover"></div><div><h4>${esc(k.lastBook.title)}</h4><p>${esc(k.lastBook.code)} • ${esc(k.lastBook.category)} • الرف ${esc(k.lastBook.shelf)}</p></div></div><div class="success-box">✓ تمت الاستعارة — الإرجاع المتوقع ${formatISODate(k.lastLoanDueISO)}</div>`:`<div class="info-banner" style="margin-top:14px">تم التعرف على الطالب. امسح الكتاب.</div>`}<div class="session-strip"><span>مهلة مسح الكتاب</span><b id="sessionCountdown">${state.config.autoClose?state.config.sessionSeconds+' ث':'يدوي'}</b></div><div class="kiosk-actions"><button class="btn primary" id="finishSession">إنهاء الجلسة</button></div></div>`}

function students(){return `<div class="section-title"><div><h2>الطلاب</h2><p>سجل كامل لكل طالب، بطاقات باركود، RFID واستيراد جماعي.</p></div><div class="toolbar-wrap"><label class="btn secondary file-btn">استيراد Excel/CSV<input id="studentImportFile" type="file" accept=".xlsx,.csv,.txt" hidden></label><button class="btn ghost" id="studentTemplateBtn">قالب Excel/CSV</button><button class="btn secondary" id="printAllStudents">طباعة البطاقات</button><button class="btn primary" id="addStudentBtn">+ طالب</button></div></div><div class="info-banner"><b>الاستيراد المرن:</b> يقبل أعمدة مثل: اسم الطالب، الرقم الشخصي، الصف، الشعبة، كود الطالب، RFID. ويمكن للنظام توليد الأكواد الناقصة تلقائيًا.</div><div class="card"><div class="card-head"><div class="table-tools"><input class="search" id="studentSearch" placeholder="الاسم / الكود / الصف / الشعبة"><select class="select" id="studentStatusFilter"><option value="">كل الحالات</option><option>نشط</option><option>موقوف</option></select></div><span>${state.students.length} طالب</span></div><div id="studentTableWrap">${studentTable(state.students)}</div></div>`}
function studentTable(data){return `<div class="table-scroll"><table class="data-table"><thead><tr><th>الكود</th><th>الطالب</th><th>الرقم الشخصي</th><th>الصف / الشعبة</th><th>الكتب</th><th>RFID</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody>${data.map(s=>`<tr><td><b>${esc(s.code)}</b></td><td><button class="link-btn" onclick="openStudentRecord('${esc(s.code)}')">${esc(s.name)}</button></td><td>${maskPid(s.personalId)}</td><td>${esc(s.grade)} / ${esc(s.section)}</td><td>${s.loans||0}</td><td>${s.rfidTag?'<span class="status available">مرتبط</span>':'—'}</td><td><span class="status ${statusClass(s.status)}">${esc(s.status)}</span></td><td><div class="row-actions"><button class="btn ghost btn-sm" onclick="openStudentRecord('${esc(s.code)}')">السجل</button><button class="btn ghost btn-sm" onclick="printStudentCard('${esc(s.code)}')">بطاقة</button><button class="btn secondary btn-sm" onclick="openStudentModal('${esc(s.code)}')">تعديل</button><button class="btn ghost btn-sm" onclick="toggleStudentStatus('${esc(s.code)}')">${s.status==='نشط'?'إيقاف':'تفعيل'}</button></div></td></tr>`).join('')}</tbody></table></div>`}

function books(){return `<div class="section-title"><div><h2>الكتب والنسخ</h2><p>كل نسخة لها باركود مستقل وسجل استعارة وحجز وRFID اختياري.</p></div><div class="toolbar-wrap"><label class="btn secondary file-btn">استيراد Excel/CSV<input id="bookImportFile" type="file" accept=".xlsx,.csv,.txt" hidden></label><button class="btn ghost" id="bookTemplateBtn">قالب Excel/CSV</button><button class="btn secondary" id="printAllBooks">طباعة الملصقات</button><button class="btn primary" id="addBookBtn">+ كتاب</button></div></div><div class="card"><div class="card-head"><div class="table-tools"><input class="search" id="bookSearch" placeholder="العنوان / الباركود / المؤلف"><select class="select" id="bookStatusFilter"><option value="">كل الحالات</option><option>متاح</option><option>مستعار</option><option>موقوف</option></select></div><span>${state.books.length} نسخة</span></div><div id="bookTableWrap">${bookTable(state.books)}</div></div>`}
function bookTable(data){return `<div class="table-scroll"><table class="data-table"><thead><tr><th>باركود النسخة</th><th>العنوان</th><th>المؤلف</th><th>التصنيف</th><th>الرف</th><th>RFID</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody>${data.map(b=>`<tr><td><b>${esc(b.code)}</b></td><td><button class="link-btn" onclick="openBookRecord('${esc(b.code)}')">${esc(b.title)}</button></td><td>${esc(b.author||'—')}</td><td>${esc(b.category)}</td><td>${esc(b.shelf)}</td><td>${b.rfidTag?'<span class="status available">مرتبط</span>':'—'}</td><td><span class="status ${statusClass(b.status)}">${esc(b.status)}</span></td><td><div class="row-actions"><button class="btn ghost btn-sm" onclick="openBookRecord('${esc(b.code)}')">السجل</button><button class="btn ghost btn-sm" onclick="printBookLabel('${esc(b.code)}')">ملصق</button><button class="btn secondary btn-sm" onclick="openBookModal('${esc(b.code)}')">تعديل</button>${b.status==='مستعار'?'':`<button class="btn ghost btn-sm" onclick="toggleBookStatus('${esc(b.code)}')">${b.status==='متاح'?'إيقاف':'إتاحة'}</button>`}</div></td></tr>`).join('')}</tbody></table></div>`}

function loans(){return `<div class="section-title"><div><h2>الاستعارات</h2><p>التجديد، الإرجاع وسجل الدورة الكاملة لكل نسخة.</p></div><button class="btn primary" onclick="render('kiosk')">+ استعارة جديدة</button></div><div class="kpis"><div class="kpi"><small>نشطة</small><strong>${activeLoans().length}</strong><div class="trend up">حاليًا</div></div><div class="kpi"><small>اليوم</small><strong>${todayLoans().length}</strong><div class="trend up">استعارة</div></div><div class="kpi"><small>إرجاعات اليوم</small><strong>${returnedToday().length}</strong><div class="trend up">عملية</div></div><div class="kpi"><small>متأخرة</small><strong>${overdueLoans().length}</strong><div class="trend down">متابعة</div></div></div><div class="card"><div class="card-head"><div class="table-tools"><input id="loanSearch" class="search" placeholder="الطالب أو الكتاب"><select id="loanStatusFilter" class="select"><option value="">كل الحالات</option><option>مستعار</option><option>متأخر</option><option>تم الإرجاع</option></select></div><button class="btn ghost" id="exportLoansBtn">تصدير CSV</button></div><div id="loanTableWrap">${loanTable(state.loans)}</div></div>`}

function circulationEventRows(date,type='all',q=''){
  const query=String(q||'').trim().toLowerCase(), rows=[];
  for(const l of state.loans){
    const hay=[l.student,l.studentCode,l.book,l.bookCode].join(' ').toLowerCase();
    if(query&&!hay.includes(query))continue;
    if((type==='all'||type==='checkout')&&l.loanDateISO===date){
      rows.push({kind:'checkout',kindLabel:'استعارة',eventISO:l.createdISO||`${l.loanDateISO}T12:00:00`,student:l.student,studentCode:l.studentCode,book:l.book,bookCode:l.bookCode,loanDateISO:l.loanDateISO,dueDateISO:l.dueDateISO,returnedDateISO:l.returnedDateISO,status:l.status,station:l.checkoutStationName||stationName(l.stationId),loan:l});
    }
    if((type==='all'||type==='return')&&l.returnedDateISO===date){
      rows.push({kind:'return',kindLabel:'إرجاع',eventISO:l.returnedISO||`${l.returnedDateISO}T12:00:00`,student:l.student,studentCode:l.studentCode,book:l.book,bookCode:l.bookCode,loanDateISO:l.loanDateISO,dueDateISO:l.dueDateISO,returnedDateISO:l.returnedDateISO,status:'تم الإرجاع',station:l.returnStationName||'—',loan:l});
    }
  }
  return rows.sort((a,b)=>String(b.eventISO||'').localeCompare(String(a.eventISO||'')));
}
function circulationRowsTable(rows){
  return rows.length?`<div class="table-scroll"><table class="data-table circulation-table"><thead><tr><th>العملية</th><th>الطالب</th><th>الكتاب</th><th>تاريخ الاستعارة</th><th>موعد الإرجاع</th><th>تاريخ الإرجاع الفعلي</th><th>المحطة</th><th>الحالة</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="operation-badge ${r.kind}">${r.kind==='checkout'?'⇄':'↩'} ${r.kindLabel}</span></td><td><button class="link-btn" onclick="openStudentRecord('${esc(r.studentCode)}')">${esc(r.student)}</button><br><small>${esc(r.studentCode)}</small></td><td><button class="link-btn" onclick="openBookRecord('${esc(r.bookCode)}')">${esc(r.book)}</button><br><small>${esc(r.bookCode)}</small></td><td>${formatISODate(r.loanDateISO)}</td><td>${formatISODate(r.dueDateISO)}</td><td>${formatISODate(r.returnedDateISO)}</td><td>${esc(r.station||'—')}</td><td><span class="status ${statusClass(r.status)}">${esc(r.status)}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">لا توجد عمليات في هذا التاريخ.</div>';
}
function circulation(){
  const date=todayISO(), rows=circulationEventRows(date), out=rows.filter(x=>x.kind==='checkout').length, back=rows.filter(x=>x.kind==='return').length;
  return `<div class="section-title"><div><h2>حركة الاستعارة اليومية</h2><p>اختر أي تاريخ لعرض جميع عمليات الاستعارة والإرجاع التي تمت فيه.</p></div><div class="toolbar-wrap"><button class="btn secondary" onclick="render('loans')">الاستعارات القائمة الآن (${activeLoans().length})</button><button class="btn ghost" id="exportCirculationBtn">تصدير اليوم</button></div></div>
  <div class="card circulation-filter-card"><div class="circulation-filter-grid"><div class="field"><label>التاريخ</label><input id="circDate" type="date" value="${date}"></div><div class="field"><label>نوع الحركة</label><select id="circType"><option value="all">كل العمليات</option><option value="checkout">الاستعارات فقط</option><option value="return">الإرجاعات فقط</option></select></div><div class="field"><label>بحث</label><input id="circSearch" placeholder="اسم الطالب، الكود، الكتاب..."></div><div class="date-shortcuts"><button class="btn ghost btn-sm" id="circTodayBtn">اليوم</button><button class="btn ghost btn-sm" id="circYesterdayBtn">أمس</button></div></div></div>
  <div class="kpis circulation-kpis"><div class="kpi"><small>إجمالي حركات اليوم المحدد</small><strong id="circTotalKpi">${rows.length}</strong><div class="trend up">استعارة + إرجاع</div></div><div class="kpi"><small>الاستعارات</small><strong id="circCheckoutKpi">${out}</strong><div class="trend up">في التاريخ المحدد</div></div><div class="kpi"><small>الإرجاعات</small><strong id="circReturnKpi">${back}</strong><div class="trend up">في التاريخ المحدد</div></div><div class="kpi"><small>قائمة الآن</small><strong>${activeLoans().length}</strong><div class="trend ${overdueLoans().length?'down':'up'}">${overdueLoans().length} متأخر</div></div></div>
  <div class="card"><div class="card-head"><div><h3 id="circTableTitle">عمليات ${formatISODate(date)}</h3><span id="circTableCount">${rows.length} عملية</span></div><span>DAILY CIRCULATION</span></div><div id="circulationTableWrap">${circulationRowsTable(rows)}</div></div>`;
}
function bindCirculationView(){
  const dateEl=$('#circDate'),typeEl=$('#circType'),searchEl=$('#circSearch'),wrap=$('#circulationTableWrap');
  const refresh=()=>{
    const date=dateEl?.value||todayISO(),type=typeEl?.value||'all',q=searchEl?.value||'',rows=circulationEventRows(date,type,q);
    const allRows=circulationEventRows(date,'all',q);
    const co=allRows.filter(x=>x.kind==='checkout').length,rt=allRows.filter(x=>x.kind==='return').length;
    if(wrap)wrap.innerHTML=circulationRowsTable(rows);
    if($('#circTotalKpi'))$('#circTotalKpi').textContent=allRows.length;
    if($('#circCheckoutKpi'))$('#circCheckoutKpi').textContent=co;
    if($('#circReturnKpi'))$('#circReturnKpi').textContent=rt;
    if($('#circTableTitle'))$('#circTableTitle').textContent=`عمليات ${formatISODate(date)}`;
    if($('#circTableCount'))$('#circTableCount').textContent=`${rows.length} عملية`;
    const btn=$('#exportCirculationBtn');if(btn)btn.textContent=`تصدير ${formatISODate(date)}`;
  };
  dateEl?.addEventListener('change',refresh);typeEl?.addEventListener('change',refresh);searchEl?.addEventListener('input',refresh);
  $('#circTodayBtn')?.addEventListener('click',()=>{dateEl.value=todayISO();refresh()});
  $('#circYesterdayBtn')?.addEventListener('click',()=>{dateEl.value=addDaysISO(-1);refresh()});
  $('#exportCirculationBtn')?.addEventListener('click',()=>{
    const date=dateEl?.value||todayISO(),type=typeEl?.value||'all',q=searchEl?.value||'',rows=circulationEventRows(date,type,q);
    downloadCSV(`circulation-${date}.csv`,[['العملية','الطالب','كود الطالب','الكتاب','كود الكتاب','تاريخ الاستعارة','موعد الإرجاع','تاريخ الإرجاع الفعلي','المحطة','الحالة'],...rows.map(r=>[r.kindLabel,r.student,r.studentCode,r.book,r.bookCode,r.loanDateISO,r.dueDateISO,r.returnedDateISO||'',r.station||'',r.status])]);
  });
}

function loanTable(data){return data.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>الطالب</th><th>الكتاب</th><th>الاستعارة</th><th>الاستحقاق</th><th>التجديد</th><th>المحطة</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${data.slice().sort((a,b)=>(b.createdISO||'').localeCompare(a.createdISO||'')).map(l=>`<tr><td><button class="link-btn" onclick="openStudentRecord('${esc(l.studentCode)}')">${esc(l.student)}</button><br><small>${esc(l.studentCode)}</small></td><td><button class="link-btn" onclick="openBookRecord('${esc(l.bookCode)}')">${esc(l.book)}</button><br><small>${esc(l.bookCode)}</small></td><td>${formatISODate(l.loanDateISO)}</td><td>${formatISODate(l.dueDateISO)}</td><td>${l.renewalsUsed||0}/${state.config.renewals}</td><td>${esc(stationName(l.stationId))}</td><td><span class="status ${statusClass(l.status)}">${esc(l.status)}</span></td><td><div class="row-actions">${['مستعار','متأخر'].includes(l.status)?`<button class="btn secondary btn-sm" onclick="renewLoan('${esc(l.id)}')">تجديد</button><button class="btn success btn-sm" onclick="returnLoanById('${esc(l.id)}')">إرجاع</button>`:`<span class="muted-text">${formatISODate(l.returnedDateISO)}</span>`}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">لا توجد استعارات.</div>'}

function returns(){return `<div class="return-layout"><div class="card return-card"><div class="return-icon">↩</div><h2>الإرجاع السريع</h2><p>امسح باركود الكتاب أو RFID. لا تحتاج بطاقة الطالب.</p><input id="returnScan" class="big-scan" placeholder="امسح الكتاب ثم Enter" autofocus><div class="scanner-ready dark">${esc(currentStation().name)} • ${esc(currentStation().readerMode)}</div><div id="returnResult"></div></div><div class="card"><div class="card-head"><h3>آخر الإرجاعات</h3><span>اليوم</span></div><div class="mini-list">${state.loans.filter(l=>l.returnedDateISO===todayISO()).slice(-5).reverse().map(l=>`<div class="mini-row"><div class="book-dot"></div><div><b>${esc(l.book)}</b><span>${esc(l.student)}</span></div><em>تم</em></div>`).join('')||'<div class="empty-state">لا توجد إرجاعات اليوم</div>'}</div></div></div>`}
function overdue(){const rows=overdueLoans();return `<div class="section-title"><div><h2>المتأخرات</h2><p>الكتب التي تجاوزت تاريخ الإرجاع.</p></div><button class="btn ghost" id="exportOverdueBtn">تصدير CSV</button></div><div class="card">${rows.length?loanTable(rows):'<div class="empty-state">ممتاز! لا توجد كتب متأخرة حاليًا.</div>'}</div>`}

function reservations(){const active=activeReservations();return `<div class="section-title"><div><h2>الحجوزات</h2><p>إنشاء وإدارة قائمة انتظار للكتب غير المتاحة.</p></div><button class="btn primary" id="addReservationBtn">+ حجز جديد</button></div><div class="kpis"><div class="kpi"><small>نشطة</small><strong>${active.length}</strong><div class="trend up">حجز</div></div><div class="kpi"><small>تمت</small><strong>${state.reservations.filter(r=>r.status==='مكتمل').length}</strong><div class="trend up">مستلمة</div></div><div class="kpi"><small>ملغاة</small><strong>${state.reservations.filter(r=>r.status==='ملغي').length}</strong><div class="trend warn">سجل</div></div><div class="kpi"><small>كتب محجوزة</small><strong>${new Set(active.map(r=>r.bookCode)).size}</strong><div class="trend up">نسخة</div></div></div><div class="card">${reservationTable(state.reservations)}</div>`}
function reservationTable(data){return data.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>الطالب</th><th>الكتاب</th><th>تاريخ الحجز</th><th>الترتيب</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${data.slice().sort((a,b)=>(b.createdISO||'').localeCompare(a.createdISO||'')).map(r=>`<tr><td>${esc(studentName(r.studentCode))}<br><small>${esc(r.studentCode)}</small></td><td>${esc(bookTitle(r.bookCode))}<br><small>${esc(r.bookCode)}</small></td><td>${formatISODate((r.createdISO||'').slice(0,10))}</td><td>${r.status==='نشط'?reservationQueuePosition(r):'—'}</td><td><span class="status ${statusClass(r.status)}">${esc(r.status)}</span></td><td>${r.status==='نشط'?`<button class="btn danger btn-sm" onclick="cancelReservation('${esc(r.id)}')">إلغاء</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">لا توجد حجوزات.</div>'}
function studentName(code){return state.students.find(s=>s.code===code)?.name||code} function bookTitle(code){return state.books.find(b=>b.code===code)?.title||code}
function reservationQueuePosition(r){return activeReservations().filter(x=>x.bookCode===r.bookCode&&(x.createdISO||'')<=(r.createdISO||'')).length}

function reports(){const grades=[...new Set(state.students.map(s=>s.grade).filter(Boolean))],cats=[...new Set(state.books.map(b=>b.category).filter(Boolean))];return `<div class="section-title"><div><h2>التقارير والإحصائيات</h2><p>فلترة حسب التاريخ والصف والتصنيف والمحطة ثم التصدير والطباعة.</p></div><div><button class="btn ghost" id="printReportBtn">طباعة</button> <button class="btn secondary" id="exportReportBtn">تصدير CSV</button></div></div><div class="card report-filter"><div class="form-grid"><div class="field"><label>من تاريخ</label><input type="date" id="repFrom" value="${addDaysISO(-30)}"></div><div class="field"><label>إلى تاريخ</label><input type="date" id="repTo" value="${todayISO()}"></div><div class="field"><label>الصف</label><select id="repGrade"><option value="">كل الصفوف</option>${grades.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>التصنيف</label><select id="repCategory"><option value="">كل التصنيفات</option>${cats.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>المحطة</label><select id="repStation"><option value="">كل المحطات</option>${state.stations.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>&nbsp;</label><button id="runReportBtn" class="btn primary wide" style="margin:0">تطبيق الفلاتر</button></div></div></div><div id="reportOutput">${reportOutput(getReportData())}</div>`}
function getReportData(){const from=$('#repFrom')?.value||addDaysISO(-30),to=$('#repTo')?.value||todayISO(),grade=$('#repGrade')?.value||'',cat=$('#repCategory')?.value||'',station=$('#repStation')?.value||'';return state.loans.filter(l=>{const s=state.students.find(x=>x.code===l.studentCode),b=state.books.find(x=>x.code===l.bookCode),d=l.loanDateISO||'';return (!from||d>=from)&&(!to||d<=to)&&(!grade||s?.grade===grade)&&(!cat||b?.category===cat)&&(!station||l.stationId===station)})}
function reportOutput(data){
  const unique=new Set(data.map(l=>l.studentCode)).size,returns=data.filter(l=>l.status==='تم الإرجاع').length,late=data.filter(l=>l.status==='متأخر').length;
  const byBook={},byStudent={},byGrade={},byCategory={},byStation={};
  data.forEach(l=>{
    byBook[l.bookCode]=(byBook[l.bookCode]||0)+1;byStudent[l.studentCode]=(byStudent[l.studentCode]||0)+1;
    const g=state.students.find(s=>s.code===l.studentCode)?.grade||'غير محدد',c=state.books.find(b=>b.code===l.bookCode)?.category||'غير مصنف',st=stationName(l.stationId);
    byGrade[g]=(byGrade[g]||0)+1;byCategory[c]=(byCategory[c]||0)+1;byStation[st]=(byStation[st]||0)+1;
  });
  const top=Object.entries(byBook).sort((a,b)=>b[1]-a[1]).slice(0,8),topReaders=Object.entries(byStudent).sort((a,b)=>b[1]-a[1]).slice(0,8);
  const rank=(obj,labelFn=x=>x)=>Object.entries(obj).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([k,n],i)=>`<div><b>${i+1}</b><span>${esc(labelFn(k))}</span><em>${n}</em></div>`).join('')||'<div class="empty-state">لا بيانات</div>';
  return `<div class="kpis"><div class="kpi"><small>إجمالي الاستعارات</small><strong>${data.length}</strong><div class="trend up">ضمن الفلتر</div></div><div class="kpi"><small>طلاب مختلفون</small><strong>${unique}</strong><div class="trend up">قارئ</div></div><div class="kpi"><small>إرجاعات مكتملة</small><strong>${returns}</strong><div class="trend up">عملية</div></div><div class="kpi"><small>متأخرة حاليًا</small><strong>${late}</strong><div class="trend down">متابعة</div></div></div>
  <div class="analytics-grid"><div class="card"><div class="card-head"><h3>أكثر الكتب استعارة</h3><span>TOP BOOKS</span></div><div class="report-ranking">${top.map(([code,n],i)=>`<div><b>${i+1}</b><span>${esc(bookTitle(code))}</span><em>${n}</em></div>`).join('')||'<div class="empty-state">لا بيانات</div>'}</div></div><div class="card"><div class="card-head"><h3>أكثر الطلاب قراءة</h3><span>TOP READERS</span></div><div class="report-ranking">${topReaders.map(([code,n],i)=>`<div><b>${i+1}</b><span>${esc(studentName(code))}</span><em>${n}</em></div>`).join('')||'<div class="empty-state">لا بيانات</div>'}</div></div><div class="card"><div class="card-head"><h3>حسب التصنيف</h3><span>CATEGORY</span></div><div class="report-ranking">${rank(byCategory)}</div></div><div class="card"><div class="card-head"><h3>حسب المحطة</h3><span>STATIONS</span></div><div class="report-ranking">${rank(byStation)}</div></div></div>
  <div class="grid-2 table-card"><div class="card"><div class="card-head"><h3>الاستعارات حسب الصف</h3><span>GRADE</span></div><div class="report-ranking">${rank(byGrade)}</div></div><div class="card"><div class="card-head"><h3>مؤشرات تشغيلية</h3><span>OPERATIONS</span></div><div class="metric-list"><div><span>معدل الإرجاع داخل النطاق</span><b>${data.length?Math.round((returns/data.length)*100):0}%</b></div><div><span>متوسط استعارات الطالب النشط</span><b>${unique?(data.length/unique).toFixed(1):0}</b></div><div><span>عدد المحطات المستخدمة</span><b>${Object.keys(byStation).length}</b></div><div><span>عدد التصنيفات النشطة</span><b>${Object.keys(byCategory).length}</b></div></div></div></div>
  <div class="card table-card"><div class="card-head"><h3>تفاصيل التقرير</h3><span>${data.length} سجل</span></div>${loanTable(data)}</div>`
}

function users(){return `<div class="section-title"><div><h2>المستخدمون والصلاحيات</h2><p>يمكن إضافة أكثر من مدير للنظام، إلى جانب أمناء المكتبة ومحطات الاستعارة وحسابات المشاهدة.</p></div><button class="btn primary" id="addUserBtn">+ مستخدم</button></div><div class="info-banner"><b>إدارة مرنة:</b> أضف مديرًا ثانيًا أو ثالثًا من زر <b>+ مستخدم</b> ثم اختر دور <b>مدير النظام</b>. كلمات المرور لا تُخزن داخل البرنامج، وتتم المصادقة من خلال Supabase Auth مع RLS.</div><div class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>الاسم</th><th>البريد الإلكتروني</th><th>الدور</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${state.users.map(u=>`<tr><td><b>${esc(u.displayName)}</b></td><td>${esc(u.username)}</td><td>${esc(ROLE_LABELS[u.role]||u.role)}</td><td><span class="status ${u.active?'available':'overdue'}">${u.active?'نشط':'موقوف'}</span></td><td><div class="row-actions"><button class="btn secondary btn-sm" onclick="openUserModal('${esc(u.id)}')">تعديل</button><button class="btn ghost btn-sm" onclick="toggleUser('${esc(u.id)}')">${u.active?'إيقاف':'تفعيل'}</button></div></td></tr>`).join('')}</tbody></table></div></div>`}
function latestUserActivity(username){const x=state.activityLogs.find(l=>l.user===username);return x?formatDateTime(x.atISO):'—'}

function stations(){return `<div class="section-title"><div><h2>الأجهزة والمحطات</h2><p>تسمية كل جهاز وتتبع عملياته وتجهيزه للباركود وRFID.</p></div><button class="btn primary" id="addStationBtn">+ محطة</button></div><div class="info-banner"><b>تعدد الأجهزة:</b> جميع المحطات متصلة بقاعدة Supabase السحابية نفسها. عمليات الاستعارة والإرجاع تتم مركزيًا بمعاملات آمنة، لذلك لا يمكن استعارة النسخة نفسها من جهازين في الوقت نفسه.</div><div class="station-grid">${state.stations.map(st=>stationCard(st)).join('')}</div><div class="card table-card"><div class="card-head"><h3>جاهزية RFID</h3><span>RFID READY</span></div><div class="readiness"><div><b>${state.students.filter(s=>s.rfidTag).length}/${state.students.length}</b><span>طلاب مرتبطون بـ RFID</span></div><div><b>${state.books.filter(b=>b.rfidTag).length}/${state.books.length}</b><span>كتب مرتبطة بـ RFID</span></div><div><b>${state.stations.filter(s=>['rfid','hybrid'].includes(s.readerMode)).length}</b><span>محطات مهيأة لـ RFID</span></div></div><p class="muted-text">النظام أصبح يتعرف على الحقل RFID لكل طالب وكتاب بنفس منطق الباركود. عند شراء القارئ لاحقًا يكفي أن يرسل UID للنظام مثل قارئ لوحة المفاتيح أو يتم ربط SDK الخاص به.</p></div>`}
function stationCard(st){const current=st.id===state.config.currentStationId;return `<div class="station-card ${current?'current':''}"><div class="station-top"><div class="station-icon">▥</div><div><b>${esc(st.name)}</b><span>${esc(st.location)}</span></div><span class="status ${st.enabled?'available':'overdue'}">${st.enabled?'مفعلة':'موقوفة'}</span></div><div class="station-meta"><span>المعرف <b>${esc(st.id)}</b></span><span>القارئ <b>${esc(st.readerMode)}</b></span><span>النوع <b>${esc(st.type)}</b></span></div><div class="row-actions"><button class="btn secondary btn-sm" onclick="openStationModal('${esc(st.id)}')">تعديل</button>${current?'<span class="status loaned">المحطة الحالية</span>':`<button class="btn ghost btn-sm" onclick="setCurrentStation('${esc(st.id)}')">تعيين كحالية</button>`}</div></div>`}

function activity(){const rows=state.activityLogs.slice(0,500);return `<div class="section-title"><div><h2>سجل العمليات</h2><p>من نفذ ماذا ومن أي محطة وفي أي وقت.</p></div><div><button class="btn ghost" id="exportActivityBtn">تصدير CSV</button> ${currentUser?.role==='admin'?'<button class="btn danger" id="clearActivityBtn">مسح السجل</button>':''}</div></div><div class="card"><div class="table-scroll"><table class="data-table"><thead><tr><th>الوقت</th><th>النوع</th><th>التفاصيل</th><th>المستخدم</th><th>المحطة</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${formatDateTime(x.atISO)}</td><td><span class="status returned">${esc(x.type)}</span></td><td>${esc(x.message)}</td><td>${esc(x.user||'—')}</td><td>${esc(stationName(x.stationId))}</td></tr>`).join('')||'<tr><td colspan="5">لا توجد عمليات</td></tr>'}</tbody></table></div></div>`}

function settings(){const c=state.config;return `<div class="section-title"><div><h2>إعدادات النظام</h2><p>هوية المدرسة وسياسات الاستعارة والحجز والقارئ والنسخ الاحتياطي.</p></div><button class="btn primary" id="saveSettingsBtn">حفظ التغييرات</button></div><div class="settings-grid"><div class="card"><div class="card-head"><h3>هوية النظام</h3><span>BRANDING</span></div><div class="brand-settings-preview"><div id="settingsLogoPreview" class="settings-logo">${c.logo?`<img src="${c.logo}">`:'م'}</div><div><b id="settingsPreviewName">${esc(c.siteName)}</b><span id="settingsPreviewSchool">${esc(c.schoolName)}</span></div></div><div class="form-stack"><div class="field"><label>اسم الموقع</label><input id="cfgSiteName" value="${esc(c.siteName)}"></div><div class="field"><label>اسم المدرسة</label><input id="cfgSchoolName" value="${esc(c.schoolName)}"></div><div class="field"><label>شعار المدرسة</label><input id="cfgLogo" type="file" accept="image/*"></div><button class="btn ghost" id="clearLogoBtn">إزالة الشعار</button></div></div><div class="card"><div class="card-head"><h3>سياسة الاستعارة والحجز</h3><span>POLICY</span></div><div class="form-grid"><div class="field"><label>أقصى عدد كتب</label><input id="cfgMaxBooks" type="number" min="1" value="${c.maxBooks}"></div><div class="field"><label>مدة الاستعارة بالأيام</label><input id="cfgLoanDays" type="number" min="1" value="${c.loanDays}"></div><div class="field"><label>عدد التجديدات</label><input id="cfgRenewals" type="number" min="0" value="${c.renewals}"></div><div class="field"><label>مدة صلاحية الحجز</label><input id="cfgReservationDays" type="number" min="1" value="${c.reservationDays}"></div></div><div class="switch-row"><div><b>منع الاستعارة عند وجود تأخير</b><div class="switch-help">يوقف العملية للطالب المتأخر.</div></div><div id="cfgPreventOverdue" class="toggle ${c.preventOverdue?'on':''}"></div></div><div class="switch-row"><div><b>إغلاق جلسة الطالب تلقائيًا</b><div class="switch-help">حماية من استخدام الطالب التالي للحساب السابق.</div></div><div id="cfgAutoClose" class="toggle ${c.autoClose?'on':''}"></div></div><div class="field"><label>مهلة الجلسة بالثواني</label><input id="cfgSessionSeconds" type="number" min="5" value="${c.sessionSeconds}"></div></div><div class="card"><div class="card-head"><h3>القارئ والمحطة</h3><span>HARDWARE</span></div><div class="form-stack"><div class="field"><label>المحطة الحالية</label><select id="cfgStation">${state.stations.filter(x=>x.enabled).map(x=>`<option value="${esc(x.id)}" ${x.id===c.currentStationId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>وضع القارئ الافتراضي</label><select id="cfgReaderMode"><option value="barcode" ${c.readerMode==='barcode'?'selected':''}>Barcode</option><option value="rfid" ${c.readerMode==='rfid'?'selected':''}>RFID</option><option value="hybrid" ${c.readerMode==='hybrid'?'selected':''}>Barcode + RFID</option></select></div><div class="field"><label>اسم المحطة</label><input id="cfgKioskName" value="${esc(c.kioskName)}"></div><div class="field"><label>الموقع</label><input id="cfgKioskLocation" value="${esc(c.kioskLocation)}"></div></div></div><div class="card"><div class="card-head"><h3>النسخ الاحتياطي</h3><span>DATA</span></div><p class="muted-text">احفظ نسخة كاملة تشمل الطلاب والكتب والاستعارات والحجوزات والمستخدمين والمحطات.</p><div class="backup-actions"><button class="btn secondary" id="exportBackupBtn">تصدير نسخة JSON</button><label class="btn ghost file-btn">استعادة<input id="importBackupFile" type="file" accept=".json" hidden></label><button class="btn danger" id="resetDemoBtn">إعادة بيانات التجربة</button></div><div class="sync-status">${remoteMode?'✓ متصل بـ Supabase Cloud':'غير متصل بالسحابة'}</div></div></div>`}

function bindDynamic(view){detachGlobalScanner();clearKioskTimer();
 if(view==='kiosk'){const inp=$('#kioskScan');inp?.focus();attachGlobalScanner(inp,handleScan);$('#finishSession')?.addEventListener('click',resetKiosk);$('#exitGuestKiosk')?.addEventListener('click',showLogin);if(state.kiosk.student)startKioskTimer()}
 if(view==='returns'){const inp=$('#returnScan');inp?.focus();attachGlobalScanner(inp,code=>returnBook(code,true))}
 if(view==='students'){bindStudentView()} if(view==='books'){bindBookView()} if(view==='loans')bindLoanView(); if(view==='circulation')bindCirculationView(); if(view==='overdue')$('#exportOverdueBtn')?.addEventListener('click',()=>exportLoansCSV(overdueLoans(),'overdue'));
 if(view==='reservations')$('#addReservationBtn')?.addEventListener('click',()=>openReservationModal()); if(view==='reports')bindReports(); if(view==='users')$('#addUserBtn')?.addEventListener('click',()=>openUserModal()); if(view==='stations')$('#addStationBtn')?.addEventListener('click',()=>openStationModal());
 if(view==='activity'){if($('#clearActivityBtn'))$('#clearActivityBtn').onclick=()=>{if(confirm('مسح سجل العمليات؟')){state.activityLogs=[];saveState();render('activity')}};$('#exportActivityBtn')?.addEventListener('click',exportActivityCSV)} if(view==='settings')bindSettings(); }
function attachGlobalScanner(input,callback){let buffer='',last=0;scannerHandler=e=>{if(document.activeElement?.matches('input,textarea,select')&&document.activeElement!==input)return;const now=Date.now();if(now-last>120)buffer='';last=now;if(e.key==='Enter'){const code=(input?.value||buffer).trim();if(code){e.preventDefault();if(input)input.value='';buffer='';callback(code)}return}if(e.key.length===1){buffer+=e.key;if(input&&document.activeElement!==input)input.value=buffer}};document.addEventListener('keydown',scannerHandler,true);input?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const code=input.value.trim();input.value='';if(code)callback(code)}})}
function detachGlobalScanner(){if(scannerHandler){document.removeEventListener('keydown',scannerHandler,true);scannerHandler=null}}
function clearKioskTimer(){if(kioskTimer)clearInterval(kioskTimer);kioskTimer=null;kioskDeadline=0}
function startKioskTimer(){clearKioskTimer();if(!state.config.autoClose||!state.kiosk.student)return;kioskDeadline=Date.now()+state.config.sessionSeconds*1000;kioskTimer=setInterval(()=>{const left=Math.max(0,Math.ceil((kioskDeadline-Date.now())/1000));const el=$('#sessionCountdown');if(el)el.textContent=left+' ث';if(left<=0){clearKioskTimer();toast('تم إغلاق جلسة الطالب تلقائيًا');resetKiosk()}},250)}
function touchKioskTimer(){if(state.kiosk.student&&state.config.autoClose)startKioskTimer()}
function resetKiosk(){clearKioskTimer();state.kiosk={step:'student',student:null,lastBook:null,lastLoanDueISO:null};render('kiosk')}

function resolveStudent(id){const v=String(id).trim();return state.students.find(s=>s.code===v||s.rfidTag===v||(state.config.allowPersonalIdScan&&s.personalId===v))}
function resolveBook(id){const v=String(id).trim();return state.books.find(b=>b.code===v||b.rfidTag===v)}
async function handleScan(code){
 touchKioskTimer();
 if(!state.kiosk.student){
   if(remoteMode){const r=await cloudTransaction('student_lookup',{studentCode:String(code).trim()});if(!r?.ok){scanMsg(r?.message||'لم يتم العثور على الطالب',false);return}const s={code:r.student.code,name:r.student.name,grade:r.student.grade||'',section:r.student.section||'',status:r.student.active?'نشط':'موقوف',activeLoans:r.student.activeLoans||0,overdue:r.student.overdue||0};if(s.status!=='نشط'){scanMsg('حساب الطالب موقوف',false);return}state.kiosk.student=s;state.kiosk.step='book';render('kiosk');return}
   const s=resolveStudent(code);if(!s){scanMsg('لم يتم العثور على الطالب',false);return}state.kiosk.student=s;state.kiosk.step='book';render('kiosk');return;
 }
 const bookCode=String(code).trim();
 if(remoteMode){const br=await cloudTransaction('book_lookup',{bookCode});if(!br?.ok){scanMsg(br?.message||'لم يتم العثور على الكتاب',false);return}const result=await borrowBook(state.kiosk.student.code,br.book.copyCode);if(result.ok){state.kiosk.lastBook={code:br.book.copyCode,title:br.book.title||'كتاب',category:br.book.category||'',shelf:''};state.kiosk.lastLoanDueISO=result.dueDateISO;render('kiosk');await loadCloudState(false,true)}else scanMsg(result.message,false);return}
 const b=resolveBook(bookCode);if(!b){scanMsg('لم يتم العثور على الكتاب',false);return}const result=await borrowBook(state.kiosk.student.code,b.code);if(result.ok){state.kiosk.lastBook=resolveBook(b.code);state.kiosk.lastLoanDueISO=result.dueDateISO;render('kiosk')}else scanMsg(result.message,false)
}
async function borrowBook(studentCode,bookCode){if(remoteMode){const res=await cloudTransaction('checkout',{studentCode,bookCode,stationCode:currentStation().id,method:currentUser?.role==='kiosk'?'self':'staff'});if(res?.ok){if(currentUser?.role!=='kiosk')await loadCloudState(false,true);return {ok:true,dueDateISO:res.due_at}}return {ok:false,message:res?.message||'تعذر تنفيذ الاستعارة'}}
 refreshDerivedState();const s=state.students.find(x=>x.code===studentCode),b=state.books.find(x=>x.code===bookCode);if(!s||!b)return {ok:false,message:'بيانات الطالب أو الكتاب غير موجودة'};if(s.status!=='نشط')return {ok:false,message:'حساب الطالب موقوف'};if(b.status!=='متاح')return {ok:false,message:'الكتاب غير متاح حاليًا'};const act=state.loans.filter(l=>l.studentCode===s.code&&['مستعار','متأخر'].includes(l.status));if(act.length>=state.config.maxBooks)return {ok:false,message:`بلغ الطالب الحد الأقصى (${state.config.maxBooks})`};if(state.config.preventOverdue&&act.some(l=>l.status==='متأخر'))return {ok:false,message:'لدى الطالب كتاب متأخر؛ لا يمكن الاستعارة'};const queue=activeReservations().filter(r=>r.bookCode===b.code).sort((a,z)=>(a.createdISO||'').localeCompare(z.createdISO||''));if(queue.length&&queue[0].studentCode!==s.code)return {ok:false,message:`الكتاب محجوز لطالب آخر في قائمة الانتظار`};const due=addDaysISO(state.config.loanDays);const loan={id:`LN${Date.now()}`,studentCode:s.code,student:s.name,bookCode:b.code,book:b.title,loanDateISO:todayISO(),dueDateISO:due,returnedDateISO:null,status:'مستعار',renewalsUsed:0,stationId:currentStation().id,createdISO:nowISO()};state.loans.push(loan);b.status='مستعار';if(queue.length&&queue[0].studentCode===s.code){queue[0].status='مكتمل';queue[0].fulfilledISO=nowISO()}logActivity('استعارة',`${s.name} ← ${b.title}`,{studentCode:s.code,bookCode:b.code,stationId:currentStation().id});saveState();return {ok:true,dueDateISO:due}}

async function returnBook(identifier,show=true){if(remoteMode){const res=await cloudTransaction('return',{bookCode:String(identifier).trim(),stationCode:currentStation().id});if(res?.ok){await loadCloudState(false,true);if(show){toast('تم تسجيل الإرجاع بنجاح');render(currentView)}return {ok:true}}if(show)toast(res?.message||'تعذر الإرجاع');return {ok:false}}const b=resolveBook(identifier);if(!b){if(show)scanMsg('الكتاب غير معروف',false);return {ok:false}}const loan=state.loans.find(l=>l.bookCode===b.code&&['مستعار','متأخر'].includes(l.status));if(!loan){if(show)scanMsg('لا توجد استعارة نشطة لهذا الكتاب',false);return {ok:false}}return returnLoanById(loan.id,show)}
async function returnLoanById(id,show=true){if(remoteMode){const loan=state.loans.find(x=>x.id===id);if(!loan)return {ok:false};return returnBook(loan.bookCode,show)}
 const l=state.loans.find(x=>x.id===id);if(!l||!['مستعار','متأخر'].includes(l.status)){toast('الاستعارة غير نشطة');return {ok:false}}l.status='تم الإرجاع';l.returnedDateISO=todayISO();const b=state.books.find(x=>x.code===l.bookCode);if(b)b.status='متاح';logActivity('إرجاع',`${l.book} ← ${l.student}`,{studentCode:l.studentCode,bookCode:l.bookCode});saveState();if(show){toast('تم تسجيل الإرجاع بنجاح');render(currentView)}return {ok:true}}
async function renewLoan(id){if(remoteMode){const loan=state.loans.find(x=>x.id===id);if(!loan)return;const res=await cloudTransaction('renew',{studentCode:loan.studentCode,bookCode:loan.bookCode});if(res?.ok){await loadCloudState(false,true);toast('تم التجديد');render('loans')}else toast(res?.message||'تعذر التجديد');return}
 const l=state.loans.find(x=>x.id===id);if(!l||!['مستعار','متأخر'].includes(l.status)){toast('الاستعارة غير قابلة للتجديد');return}if((l.renewalsUsed||0)>=state.config.renewals){toast('تم استنفاد عدد مرات التجديد');return}const waiting=activeReservations().some(r=>r.bookCode===l.bookCode&&r.studentCode!==l.studentCode);if(waiting){toast('لا يمكن التجديد: يوجد حجز لطالب آخر');return}const base=(l.dueDateISO>todayISO()?l.dueDateISO:todayISO());l.dueDateISO=addDaysISO(state.config.loanDays,new Date(base+'T12:00:00'));l.renewalsUsed=(l.renewalsUsed||0)+1;l.status='مستعار';logActivity('تجديد',`${l.book} للطالب ${l.student}`,{loanId:l.id,bookCode:l.bookCode,studentCode:l.studentCode});saveState();toast('تم تجديد الاستعارة');render('loans')}

function bindStudentView(){const search=()=>{const q=$('#studentSearch').value.trim().toLowerCase(),st=$('#studentStatusFilter').value;const d=state.students.filter(s=>(!q||[s.code,s.name,s.grade,s.section,s.personalId].join(' ').toLowerCase().includes(q))&&(!st||s.status===st));$('#studentTableWrap').innerHTML=studentTable(d)};$('#studentSearch').oninput=search;$('#studentStatusFilter').onchange=search;$('#addStudentBtn').onclick=()=>openStudentModal();$('#printAllStudents').onclick=printAllStudentCards;$('#studentTemplateBtn').onclick=()=>downloadStatic('templates/قالب_استيراد_الطلاب.xlsx','قالب_استيراد_الطلاب.xlsx');$('#studentImportFile').onchange=e=>importTabular(e.target.files?.[0],'students')}
function bindBookView(){const search=()=>{const q=$('#bookSearch').value.trim().toLowerCase(),st=$('#bookStatusFilter').value;const d=state.books.filter(b=>(!q||[b.code,b.title,b.author,b.category,b.isbn,b.accession].join(' ').toLowerCase().includes(q))&&(!st||b.status===st));$('#bookTableWrap').innerHTML=bookTable(d)};$('#bookSearch').oninput=search;$('#bookStatusFilter').onchange=search;$('#addBookBtn').onclick=()=>openBookModal();$('#printAllBooks').onclick=printAllBookLabels;$('#bookTemplateBtn').onclick=()=>downloadStatic('templates/قالب_استيراد_الكتب.xlsx','قالب_استيراد_الكتب.xlsx');$('#bookImportFile').onchange=e=>importTabular(e.target.files?.[0],'books')}
function bindLoanView(){const run=()=>{const q=$('#loanSearch').value.trim().toLowerCase(),st=$('#loanStatusFilter').value;const d=state.loans.filter(l=>(!q||[l.student,l.studentCode,l.book,l.bookCode].join(' ').toLowerCase().includes(q))&&(!st||l.status===st));$('#loanTableWrap').innerHTML=loanTable(d)};$('#loanSearch').oninput=run;$('#loanStatusFilter').onchange=run;$('#exportLoansBtn').onclick=()=>exportLoansCSV(state.loans,'loans')}

function openModal(title,sub,body,large=false){$('#modalTitle').textContent=title;$('#modalSub').textContent=sub||'';$('#modalBody').innerHTML=body;$('#modalBackdrop .modal-card').classList.toggle('large-modal',!!large);$('#modalBackdrop').classList.remove('hidden')}
function closeModal(){$('#modalBackdrop').classList.add('hidden');$('#modalBody').innerHTML='';$('#modalBackdrop .modal-card').classList.remove('large-modal')}
function nextStudentCode(){let n=Math.max(0,...state.students.map(s=>Number((s.code.match(/^ST(\d+)/)||[])[1]||0)))+1;return 'ST'+String(n).padStart(6,'0')}
function nextBookCode(){let n=Math.max(0,...state.books.map(b=>Number((b.code.match(/^BK(\d+)/)||[])[1]||0)))+1;return 'BK'+String(n).padStart(6,'0')+'-01'}
function nextAccession(){let n=Math.max(0,...state.books.map(b=>Number((String(b.accession).match(/(\d+)/)||[])[1]||0)))+1;return 'ACC'+String(n).padStart(6,'0')}
function openStudentModal(code=null){const s=code?state.students.find(x=>x.code===code):null;openModal(s?'تعديل الطالب':'إضافة طالب','الكود الداخلي هو ما يطبع داخل الباركود.',`<div class="modal-form"><div class="field"><label>اسم الطالب *</label><input id="mStudentName" value="${esc(s?.name||'')}"></div><div class="field"><label>الرقم الشخصي</label><input id="mStudentPid" value="${esc(s?.personalId||'')}"></div><div class="field"><label>الصف</label><input id="mStudentGrade" value="${esc(s?.grade||'')}"></div><div class="field"><label>الشعبة</label><input id="mStudentSection" value="${esc(s?.section||'')}"></div><div class="field"><label>كود الطالب</label><input id="mStudentCode" value="${esc(s?.code||nextStudentCode())}"></div><div class="field"><label>RFID UID</label><input id="mStudentRfid" value="${esc(s?.rfidTag||'')}"></div><div class="modal-actions full"><button class="btn ghost" onclick="closeModal()">إلغاء</button><button class="btn primary" id="saveStudentModal">حفظ</button></div></div>`);$('#saveStudentModal').onclick=()=>saveStudentModal(code)}
function saveStudentModal(original){const name=$('#mStudentName').value.trim(),pid=$('#mStudentPid').value.trim(),grade=$('#mStudentGrade').value.trim(),section=$('#mStudentSection').value.trim(),code=$('#mStudentCode').value.trim().toUpperCase(),rfid=$('#mStudentRfid').value.trim();if(!name||!code){toast('الاسم والكود مطلوبان');return}if(state.students.some(s=>s.code===code&&s.code!==original)){toast('كود الطالب مستخدم');return}if(pid&&state.students.some(s=>s.personalId===pid&&s.code!==original)){toast('الرقم الشخصي مستخدم لطالب آخر');return}if(rfid&&state.students.some(s=>s.rfidTag===rfid&&s.code!==original)){toast('RFID مرتبط بطالب آخر');return}if(original){Object.assign(state.students.find(s=>s.code===original),{name,personalId:pid,grade,section,code,rfidTag:rfid});state.loans.forEach(l=>{if(l.studentCode===original){l.studentCode=code;l.student=name}});state.reservations.forEach(r=>{if(r.studentCode===original)r.studentCode=code});logActivity('تعديل طالب',name,{studentCode:code})}else{state.students.push({code,name,personalId:pid,grade,section,status:'نشط',rfidTag:rfid});logActivity('إضافة طالب',name,{studentCode:code})}saveState();closeModal();render('students');toast('تم حفظ بيانات الطالب')}
function toggleStudentStatus(code){const s=state.students.find(x=>x.code===code);if(!s)return;if(s.status==='نشط'&&state.loans.some(l=>l.studentCode===code&&['مستعار','متأخر'].includes(l.status))){toast('لا يمكن إيقاف طالب لديه استعارات نشطة');return}s.status=s.status==='نشط'?'موقوف':'نشط';logActivity('حالة طالب',`${s.name}: ${s.status}`,{studentCode:code});saveState();render('students')}
function openStudentRecord(code){const s=state.students.find(x=>x.code===code);if(!s)return;const history=state.loans.filter(l=>l.studentCode===code),active=history.filter(l=>['مستعار','متأخر'].includes(l.status)),res=state.reservations.filter(r=>r.studentCode===code);openModal('سجل الطالب',s.name,`<div class="record-head"><div class="record-avatar">${esc(s.name[0])}</div><div><h2>${esc(s.name)}</h2><p>${esc(s.code)} • ${esc(s.grade)} / ${esc(s.section)}</p></div><div class="record-kpis"><span><b>${active.length}</b> حالي</span><span><b>${history.length}</b> إجمالي</span><span><b>${res.filter(r=>r.status==='نشط').length}</b> حجز</span></div></div><div class="record-grid"><div><h4>بيانات الطالب</h4><p>الرقم الشخصي: ${maskPid(s.personalId)}</p><p>RFID: ${esc(s.rfidTag||'غير مرتبط')}</p><p>الحالة: ${esc(s.status)}</p></div><div><h4>الكتب الحالية</h4>${active.length?active.map(l=>`<div class="record-line"><b>${esc(l.book)}</b><span>${formatISODate(l.dueDateISO)} • ${esc(l.status)}</span></div>`).join(''):'<p>لا توجد استعارات حالية.</p>'}</div></div><h4>السجل الكامل</h4>${loanTable(history)}<h4 style="margin-top:18px">الحجوزات</h4>${reservationTable(res)}`,true)}

function openBookModal(code=null){const b=code?state.books.find(x=>x.code===code):null;openModal(b?'تعديل الكتاب':'إضافة كتاب','كل نسخة فعلية يجب أن تحصل على كود مستقل.',`<div class="modal-form"><div class="field full"><label>عنوان الكتاب *</label><input id="mBookTitle" value="${esc(b?.title||'')}"></div><div class="field"><label>المؤلف</label><input id="mBookAuthor" value="${esc(b?.author||'')}"></div><div class="field"><label>التصنيف</label><input id="mBookCategory" value="${esc(b?.category||'')}"></div><div class="field"><label>الرف</label><input id="mBookShelf" value="${esc(b?.shelf||'')}"></div><div class="field"><label>باركود النسخة</label><input id="mBookCode" value="${esc(b?.code||nextBookCode())}"></div><div class="field"><label>رقم العهدة</label><input id="mBookAccession" value="${esc(b?.accession||nextAccession())}"></div><div class="field"><label>ISBN</label><input id="mBookIsbn" value="${esc(b?.isbn||'')}"></div><div class="field"><label>الناشر</label><input id="mBookPublisher" value="${esc(b?.publisher||'')}"></div><div class="field"><label>السنة</label><input id="mBookYear" value="${esc(b?.year||'')}"></div><div class="field"><label>RFID UID</label><input id="mBookRfid" value="${esc(b?.rfidTag||'')}"></div><div class="modal-actions full"><button class="btn ghost" onclick="closeModal()">إلغاء</button><button class="btn primary" id="saveBookModal">حفظ</button></div></div>`);$('#saveBookModal').onclick=()=>saveBookModal(code)}
function saveBookModal(original){const title=$('#mBookTitle').value.trim(),author=$('#mBookAuthor').value.trim(),category=$('#mBookCategory').value.trim()||'غير مصنف',shelf=$('#mBookShelf').value.trim()||'—',code=$('#mBookCode').value.trim().toUpperCase(),accession=$('#mBookAccession').value.trim(),isbn=$('#mBookIsbn').value.trim(),publisher=$('#mBookPublisher').value.trim(),year=$('#mBookYear').value.trim(),rfid=$('#mBookRfid').value.trim();if(!title||!code){toast('العنوان والباركود مطلوبان');return}if(state.books.some(b=>b.code===code&&b.code!==original)){toast('باركود النسخة مستخدم');return}if(rfid&&state.books.some(b=>b.rfidTag===rfid&&b.code!==original)){toast('RFID مرتبط بكتاب آخر');return}if(original){const b=state.books.find(x=>x.code===original);Object.assign(b,{title,author,category,shelf,code,accession,isbn,publisher,year,rfidTag:rfid});state.loans.forEach(l=>{if(l.bookCode===original){l.bookCode=code;l.book=title}});state.reservations.forEach(r=>{if(r.bookCode===original)r.bookCode=code});logActivity('تعديل كتاب',title,{bookCode:code})}else{state.books.push({code,title,author,category,shelf,accession,isbn,publisher,year,rfidTag:rfid,status:'متاح'});logActivity('إضافة كتاب',title,{bookCode:code})}saveState();closeModal();render('books');toast('تم حفظ الكتاب')}
async function toggleBookStatus(code){const b=state.books.find(x=>x.code===code);if(!b)return;if(['مستعار','محجوز'].includes(b.status)){toast('لا يمكن إيقاف نسخة مستعارة أو محجوزة');return}b.status=b.status==='متاح'?'موقوف':'متاح';if(remoteMode&&b.dbCopyId){const {error}=await sb.from('book_copies').update({status:arBookStatusToDb(b.status)}).eq('id',b.dbCopyId);if(error){toast('تعذر تغيير حالة النسخة');await loadCloudState(false,true);render('books');return}}logActivity('حالة كتاب',`${b.title}: ${b.status}`,{bookCode:code});persistLocal();render('books')}
function openBookRecord(code){const b=state.books.find(x=>x.code===code);if(!b)return;const history=state.loans.filter(l=>l.bookCode===code),active=history.find(l=>['مستعار','متأخر'].includes(l.status)),res=state.reservations.filter(r=>r.bookCode===code);openModal('سجل الكتاب',b.title,`<div class="record-head"><div class="book-cover large"></div><div><h2>${esc(b.title)}</h2><p>${esc(b.code)} • ${esc(b.category)} • الرف ${esc(b.shelf)}</p></div><div class="record-kpis"><span><b>${history.length}</b> استعارة</span><span><b>${res.filter(r=>r.status==='نشط').length}</b> حجز</span><span><b>${esc(b.status)}</b> الحالة</span></div></div><div class="record-grid"><div><h4>بيانات ببليوجرافية</h4><p>المؤلف: ${esc(b.author||'—')}</p><p>ISBN: ${esc(b.isbn||'—')}</p><p>الناشر: ${esc(b.publisher||'—')}</p><p>السنة: ${esc(b.year||'—')}</p><p>العهدة: ${esc(b.accession||'—')}</p><p>RFID: ${esc(b.rfidTag||'غير مرتبط')}</p></div><div><h4>الوضع الحالي</h4>${active?`<p>مع الطالب: <b>${esc(active.student)}</b></p><p>حتى: ${formatISODate(active.dueDateISO)}</p><button class="btn success" onclick="closeModal();returnLoanById('${esc(active.id)}')">إرجاع الآن</button>`:'<p>النسخة متاحة للاستعارة.</p>'}</div></div><h4>سجل الاستعارة</h4>${loanTable(history)}<h4 style="margin-top:18px">قائمة الحجز</h4>${reservationTable(res)}`,true)}

function openReservationModal(){openModal('حجز كتاب','اختر الطالب والنسخة المطلوب حجزها.',`<div class="modal-form"><div class="field full"><label>الطالب</label><select id="resStudent">${state.students.filter(s=>s.status==='نشط').map(s=>`<option value="${esc(s.code)}">${esc(s.name)} — ${esc(s.code)}</option>`).join('')}</select></div><div class="field full"><label>الكتاب</label><select id="resBook">${state.books.filter(b=>b.status!=='موقوف').map(b=>`<option value="${esc(b.code)}">${esc(b.title)} — ${esc(b.code)} — ${esc(b.status)}</option>`).join('')}</select></div><div class="modal-actions full"><button class="btn ghost" onclick="closeModal()">إلغاء</button><button class="btn primary" id="saveReservationBtn">تأكيد الحجز</button></div></div>`);$('#saveReservationBtn').onclick=()=>createReservation($('#resStudent').value,$('#resBook').value)}
async function createReservation(studentCode,bookCode){if(remoteMode){const b=state.books.find(x=>x.code===bookCode);if(!b?.dbBookId){toast('تعذر تحديد سجل الكتاب');return}const res=await cloudTransaction('reserve',{studentCode,bookId:b.dbBookId});if(res?.ok){await loadCloudState(false,true);closeModal();render('reservations');toast('تم إنشاء الحجز')}else toast(res?.message||'تعذر الحجز');return}if(state.reservations.some(r=>r.studentCode===studentCode&&r.bookCode===bookCode&&r.status==='نشط')){toast('يوجد حجز نشط بالفعل');return}const r={id:`RS${Date.now()}`,studentCode,bookCode,status:'نشط',createdISO:nowISO(),expiresISO:null};state.reservations.push(r);logActivity('حجز',`${studentName(studentCode)} حجز ${bookTitle(bookCode)}`,{studentCode,bookCode});saveState();closeModal();render('reservations');toast('تم إنشاء الحجز')}
async function cancelReservation(id){if(remoteMode){const res=await cloudTransaction('cancel_reservation',{reservationId:id});if(res?.ok){await loadCloudState(false,true);render('reservations')}else toast(res?.message||'تعذر الإلغاء');return}const r=state.reservations.find(x=>x.id===id);if(!r)return;r.status='ملغي';r.cancelledISO=nowISO();logActivity('إلغاء حجز',`${studentName(r.studentCode)} — ${bookTitle(r.bookCode)}`,{studentCode:r.studentCode,bookCode:r.bookCode});saveState();render('reservations')}

function openUserModal(id=null){const u=id?state.users.find(x=>x.id===id):null;openModal(u?'تعديل مستخدم':'إضافة مستخدم','الحساب محفوظ في Supabase Auth.',`<div class="modal-form"><div class="field"><label>الاسم الظاهر</label><input id="mUserDisplay" value="${esc(u?.displayName||'')}"></div><div class="field"><label>البريد الإلكتروني</label><input id="mUsername" type="email" value="${esc(u?.username||'')}" ${u?'disabled':''}></div><div class="field"><label>كلمة المرور ${u?'(اختياري للتغيير)':''}</label><input id="mUserPass" type="password" value=""></div><div class="field"><label>الدور</label><select id="mUserRole"><option value="admin" ${u?.role==='admin'?'selected':''}>مدير النظام</option><option value="librarian" ${u?.role==='librarian'?'selected':''}>أمين المكتبة</option><option value="kiosk" ${u?.role==='kiosk'?'selected':''}>محطة استعارة</option><option value="viewer" ${u?.role==='viewer'?'selected':''}>مشاهدة فقط</option></select></div><div class="modal-actions full"><button class="btn ghost" onclick="closeModal()">إلغاء</button><button class="btn primary" id="saveUserBtn">حفظ</button></div></div>`);$('#saveUserBtn').onclick=()=>saveUser(id)}
async function saveUser(id){const fullName=$('#mUserDisplay').value.trim(),email=$('#mUsername').value.trim(),password=$('#mUserPass').value,role=$('#mUserRole').value;if(!fullName||(!id&&!email)||(!id&&password.length<6)){toast('أكمل البيانات، وكلمة المرور 6 أحرف على الأقل');return}const body=id?{action:'update',schoolId:CLOUD.schoolId,userId:id,fullName,role,active:state.users.find(x=>x.id===id)?.active!==false}:{action:'create',schoolId:CLOUD.schoolId,email,password,fullName,role};const {data,error}=await sb.functions.invoke('library-users',{body});if(error||!data?.ok){toast(data?.message||error?.message||'تعذر حفظ المستخدم');return}if(id&&password){const rr=await sb.functions.invoke('library-users',{body:{action:'password',schoolId:CLOUD.schoolId,userId:id,password}});if(rr.error||!rr.data?.ok){toast(rr.data?.message||'تم حفظ البيانات لكن تعذر تغيير كلمة المرور')}}await loadCloudUsers();closeModal();render('users');toast('تم حفظ المستخدم')}
async function toggleUser(id){const u=state.users.find(x=>x.id===id);if(!u)return;if(id===authUser?.id&&u.active){toast('لا يمكن إيقاف حسابك الحالي');return}const {data,error}=await sb.functions.invoke('library-users',{body:{action:'update',schoolId:CLOUD.schoolId,userId:id,fullName:u.displayName,role:u.role,active:!u.active}});if(error||!data?.ok){toast(data?.message||'تعذر تغيير الحالة');return}await loadCloudUsers();render('users')}

function openStationModal(id=null){const s=id?state.stations.find(x=>x.id===id):null;openModal(s?'تعديل المحطة':'إضافة محطة','اسم كل جهاز يظهر في سجل العمليات والتقارير.',`<div class="modal-form"><div class="field"><label>معرف المحطة</label><input id="mStationId" value="${esc(s?.id||`KIOSK-${String(state.stations.length+1).padStart(2,'0')}`)}"></div><div class="field"><label>الاسم</label><input id="mStationName" value="${esc(s?.name||'')}"></div><div class="field"><label>الموقع</label><input id="mStationLocation" value="${esc(s?.location||'')}"></div><div class="field"><label>النوع</label><select id="mStationType"><option value="self_checkout" ${s?.type==='self_checkout'?'selected':''}>استعارة ذاتية</option><option value="desk" ${s?.type==='desk'?'selected':''}>مكتب الموظف</option><option value="return" ${s?.type==='return'?'selected':''}>إرجاع ذاتي</option></select></div><div class="field"><label>القارئ</label><select id="mStationReader"><option value="barcode" ${s?.readerMode==='barcode'?'selected':''}>Barcode</option><option value="rfid" ${s?.readerMode==='rfid'?'selected':''}>RFID</option><option value="hybrid" ${s?.readerMode==='hybrid'?'selected':''}>Hybrid</option></select></div><div class="modal-actions full"><button class="btn ghost" onclick="closeModal()">إلغاء</button><button class="btn primary" id="saveStationBtn">حفظ</button></div></div>`);$('#saveStationBtn').onclick=()=>saveStation(id)}
function saveStation(original){const id=$('#mStationId').value.trim().toUpperCase(),name=$('#mStationName').value.trim(),location=$('#mStationLocation').value.trim(),type=$('#mStationType').value,readerMode=$('#mStationReader').value;if(!id||!name){toast('المعرف والاسم مطلوبان');return}if(state.stations.some(s=>s.id===id&&s.id!==original)){toast('معرف المحطة مستخدم');return}if(original){const st=state.stations.find(s=>s.id===original);Object.assign(st,{id,name,location,type,readerMode});if(state.config.currentStationId===original)state.config.currentStationId=id;state.loans.forEach(l=>{if(l.stationId===original)l.stationId=id})}else state.stations.push({id,name,location,type,readerMode,enabled:true});logActivity('محطة',`${original?'تعديل':'إضافة'} ${name}`,{stationId:id});saveState();closeModal();render('stations')}
function setCurrentStation(id){state.config.currentStationId=id;const st=state.stations.find(x=>x.id===id);state.config.kioskName=st?.name||state.config.kioskName;state.config.kioskLocation=st?.location||state.config.kioskLocation;saveState();render('stations');toast('تم تعيين المحطة الحالية')}

function bindReports(){const run=()=>$('#reportOutput').innerHTML=reportOutput(getReportData());['#repFrom','#repTo','#repGrade','#repCategory','#repStation'].forEach(id=>$(id)?.addEventListener('change',run));$('#runReportBtn').onclick=run;$('#exportReportBtn').onclick=()=>exportLoansCSV(getReportData(),'report');$('#printReportBtn').onclick=()=>window.print()}
function bindSettings(){const preview=()=>{$('#settingsPreviewName').textContent=$('#cfgSiteName').value||'اسم النظام';$('#settingsPreviewSchool').textContent=$('#cfgSchoolName').value||'اسم المدرسة'};$('#cfgSiteName').oninput=preview;$('#cfgSchoolName').oninput=preview;$('#cfgLogo').onchange=e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>1500000){toast('الشعار كبير؛ استخدم ملفًا أقل من 1.5MB');return}const r=new FileReader();r.onload=()=>{pendingLogoData=r.result;$('#settingsLogoPreview').innerHTML=`<img src="${pendingLogoData}">`};r.readAsDataURL(f)};$('#clearLogoBtn').onclick=()=>{pendingLogoData='';$('#settingsLogoPreview').textContent='م'};['#cfgPreventOverdue','#cfgAutoClose'].forEach(id=>$(id).onclick=()=>$(id).classList.toggle('on'));$('#saveSettingsBtn').onclick=saveSettings;$('#exportBackupBtn').onclick=exportBackup;$('#importBackupFile').onchange=e=>importBackup(e.target.files?.[0]);$('#resetDemoBtn').onclick=()=>{if(confirm('سيتم حذف بيانات هذه النسخة وإرجاع بيانات التجربة.')){localStorage.removeItem(STORAGE_KEY);location.reload()}}}
function saveSettings(){const c=state.config;c.siteName=$('#cfgSiteName').value.trim()||defaults.config.siteName;c.schoolName=$('#cfgSchoolName').value.trim()||defaults.config.schoolName;c.logo=pendingLogoData;c.maxBooks=Math.max(1,Number($('#cfgMaxBooks').value)||3);c.loanDays=Math.max(1,Number($('#cfgLoanDays').value)||14);c.renewals=Math.max(0,Number($('#cfgRenewals').value)||0);c.reservationDays=Math.max(1,Number($('#cfgReservationDays').value)||3);c.preventOverdue=$('#cfgPreventOverdue').classList.contains('on');c.autoClose=$('#cfgAutoClose').classList.contains('on');c.sessionSeconds=Math.max(5,Number($('#cfgSessionSeconds').value)||10);c.currentStationId=$('#cfgStation').value;c.readerMode=$('#cfgReaderMode').value;c.kioskName=$('#cfgKioskName').value.trim();c.kioskLocation=$('#cfgKioskLocation').value.trim();logActivity('إعدادات','تم تحديث إعدادات النظام');saveState();applyBranding();render('settings');toast('تم حفظ الإعدادات')}

async function importTabular(file,type){if(!file)return;try{const rows=await readTabularFile(file);if(rows.length<2){toast('الملف لا يحتوي على بيانات');return}const parsed=type==='students'?mapStudentRows(rows):mapBookRows(rows);showImportPreview(parsed,type)}catch(e){console.error(e);toast('تعذر قراءة الملف: '+(e.message||'صيغة غير مدعومة'))}}
function normalizeHeader(x){return String(x||'').trim().toLowerCase().replace(/[\s_\-\/]+/g,'')}
function findCol(headers,aliases){const norm=headers.map(normalizeHeader);for(const a of aliases){const i=norm.indexOf(normalizeHeader(a));if(i>=0)return i}return -1}
function mapStudentRows(rows){const h=rows[0],idx={name:findCol(h,['اسم الطالب','الاسم','student name','name']),personalId:findCol(h,['الرقم الشخصي','رقم شخصي','personal id','qid','student id']),grade:findCol(h,['الصف','grade','class']),section:findCol(h,['الشعبة','الفصل','section']),code:findCol(h,['كود الطالب','الكود','student code','code','barcode']),rfidTag:findCol(h,['rfid','rfid uid','كود rfid'])};if(idx.name<0)throw new Error('لم أجد عمود اسم الطالب');let seq=0;const items=rows.slice(1).filter(r=>r.some(v=>String(v||'').trim())).map((r,i)=>{let code=idx.code>=0?String(r[idx.code]||'').trim().toUpperCase():'';if(!code){seq++;code=nextAvailableStudentCode(seq)}return {row:i+2,data:{code,name:String(r[idx.name]||'').trim(),personalId:idx.personalId>=0?String(r[idx.personalId]||'').trim():'',grade:idx.grade>=0?String(r[idx.grade]||'').trim():'',section:idx.section>=0?String(r[idx.section]||'').trim():'',rfidTag:idx.rfidTag>=0?String(r[idx.rfidTag]||'').trim():'',status:'نشط'},errors:[]}}).map(x=>validateImportStudent(x));markInternalDuplicates(items,['code','personalId','rfidTag']);return items}
function nextAvailableStudentCode(offset=1){let n=Math.max(0,...state.students.map(s=>Number((s.code.match(/^ST(\d+)/)||[])[1]||0)))+offset;return 'ST'+String(n).padStart(6,'0')}
function validateImportStudent(x){const d=x.data;if(!d.name)x.errors.push('الاسم فارغ');if(state.students.some(s=>s.code===d.code))x.errors.push('الكود موجود');if(d.personalId&&state.students.some(s=>s.personalId===d.personalId))x.errors.push('الرقم الشخصي موجود');if(d.rfidTag&&state.students.some(s=>s.rfidTag===d.rfidTag))x.errors.push('RFID موجود');return x}
function mapBookRows(rows){const h=rows[0],idx={title:findCol(h,['عنوان الكتاب','اسم الكتاب','العنوان','title']),author:findCol(h,['المؤلف','author']),category:findCol(h,['التصنيف','category']),shelf:findCol(h,['الرف','shelf']),code:findCol(h,['باركود النسخة','كود الكتاب','باركود','barcode','book code','code']),accession:findCol(h,['رقم العهدة','العهدة','accession']),isbn:findCol(h,['isbn']),publisher:findCol(h,['الناشر','publisher']),year:findCol(h,['السنة','سنة النشر','year']),rfidTag:findCol(h,['rfid','rfid uid','كود rfid'])};if(idx.title<0)throw new Error('لم أجد عمود عنوان الكتاب');let seq=0;const items=rows.slice(1).filter(r=>r.some(v=>String(v||'').trim())).map((r,i)=>{let code=idx.code>=0?String(r[idx.code]||'').trim().toUpperCase():'';if(!code){seq++;code=nextAvailableBookCode(seq)}return {row:i+2,data:{code,title:String(r[idx.title]||'').trim(),author:idx.author>=0?String(r[idx.author]||'').trim():'',category:idx.category>=0?String(r[idx.category]||'').trim()||'غير مصنف':'غير مصنف',shelf:idx.shelf>=0?String(r[idx.shelf]||'').trim()||'—':'—',accession:(idx.accession>=0&&String(r[idx.accession]||'').trim())?String(r[idx.accession]||'').trim():nextAvailableAccession(seq),isbn:idx.isbn>=0?String(r[idx.isbn]||'').trim():'',publisher:idx.publisher>=0?String(r[idx.publisher]||'').trim():'',year:idx.year>=0?String(r[idx.year]||'').trim():'',rfidTag:idx.rfidTag>=0?String(r[idx.rfidTag]||'').trim():'',status:'متاح'},errors:[]}}).map(x=>validateImportBook(x));markInternalDuplicates(items,['code','rfidTag','accession']);return items}
function nextAvailableBookCode(offset=1){let n=Math.max(0,...state.books.map(b=>Number((b.code.match(/^BK(\d+)/)||[])[1]||0)))+offset;return 'BK'+String(n).padStart(6,'0')+'-01'}
function nextAvailableAccession(offset=1){let n=Math.max(0,...state.books.map(b=>Number((String(b.accession||'').match(/(\d+)/)||[])[1]||0)))+offset;return 'ACC'+String(n).padStart(6,'0')}
function validateImportBook(x){const d=x.data;if(!d.title)x.errors.push('العنوان فارغ');if(state.books.some(b=>b.code===d.code))x.errors.push('الباركود موجود');if(d.rfidTag&&state.books.some(b=>b.rfidTag===d.rfidTag))x.errors.push('RFID موجود');return x}
function markInternalDuplicates(items,keys){for(const key of keys){const seen=new Map();for(const x of items){const v=String(x.data[key]||'').trim();if(!v)continue;if(seen.has(v)){x.errors.push(`${key} مكرر داخل الملف`);seen.get(v).errors.push(`${key} مكرر داخل الملف`)}else seen.set(v,x)}}}
function showImportPreview(items,type){const ok=items.filter(x=>!x.errors.length),bad=items.filter(x=>x.errors.length);openModal('معاينة الاستيراد',`${ok.length} صف صالح • ${bad.length} صف به مشكلة`,`<div class="import-summary"><div><b>${items.length}</b><span>إجمالي الصفوف</span></div><div class="good"><b>${ok.length}</b><span>جاهز للاستيراد</span></div><div class="bad"><b>${bad.length}</b><span>يحتاج مراجعة</span></div></div><div class="table-scroll import-preview"><table class="data-table"><thead><tr><th>الصف</th><th>${type==='students'?'الاسم':'العنوان'}</th><th>الكود</th><th>الحالة</th></tr></thead><tbody>${items.slice(0,50).map(x=>`<tr><td>${x.row}</td><td>${esc(type==='students'?x.data.name:x.data.title)}</td><td>${esc(x.data.code)}</td><td>${x.errors.length?`<span class="status overdue">${esc(x.errors.join('، '))}</span>`:'<span class="status available">جاهز</span>'}</td></tr>`).join('')}</tbody></table></div><div class="modal-actions"><button class="btn ghost" onclick="closeModal()">إلغاء</button><button class="btn primary" id="confirmImportBtn" ${ok.length?'':'disabled'}>استيراد ${ok.length} سجل</button></div>`,true);$('#confirmImportBtn')?.addEventListener('click',async()=>{if(remoteMode){const done=type==='students'?await cloudImportStudents(ok.map(x=>x.data)):await cloudImportBooks(ok.map(x=>x.data));if(!done)return;await loadCloudState(false,true)}else{if(type==='students')state.students.push(...ok.map(x=>x.data));else state.books.push(...ok.map(x=>x.data));saveState()}logActivity('استيراد',`تم استيراد ${ok.length} ${type==='students'?'طالب':'كتاب'} من ملف`);closeModal();render(type);toast(`تم استيراد ${ok.length} سجل بنجاح`)})}
async function readTabularFile(file){const name=file.name.toLowerCase();if(name.endsWith('.xlsx'))return readXlsx(await file.arrayBuffer());const text=await file.text();return parseCSV(text)}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const ch=text[i],nx=text[i+1];if(ch==='"'){if(q&&nx==='"'){cell+='"';i++}else q=!q}else if(!q&&(ch===','||ch===';'||ch==='\t')){row.push(cell.trim());cell=''}else if(!q&&(ch==='\n'||ch==='\r')){if(ch==='\r'&&nx==='\n')i++;row.push(cell.trim());if(row.some(x=>x!==''))rows.push(row);row=[];cell=''}else cell+=ch}row.push(cell.trim());if(row.some(x=>x!==''))rows.push(row);return rows}
async function readXlsx(buf){
  const files=await unzipEntries(buf),dec=new TextDecoder('utf-8'),txt=n=>files[n]?dec.decode(files[n]):'';
  const wb=txt('xl/workbook.xml'),rel=txt('xl/_rels/workbook.xml.rels');
  if(!wb||!rel)throw new Error('ملف XLSX غير صالح');
  const sheetTag=(wb.match(/<(?:\w+:)?sheet\b[^>]*>/i)||[])[0]||'';
  const sheetRel=(sheetTag.match(/\br:id="([^"]+)"/i)||[])[1];
  const relMap={};
  for(const m of rel.matchAll(/<Relationship\b[^>]*>/gi)){
    const tag=m[0],id=(tag.match(/\bId="([^"]+)"/i)||[])[1],target=(tag.match(/\bTarget="([^"]+)"/i)||[])[1];
    if(id&&target)relMap[id]=target.replace(/^\//,'');
  }
  let path=relMap[sheetRel]||'worksheets/sheet1.xml';if(!path.startsWith('xl/'))path='xl/'+path.replace(/^\.\//,'');
  const xml=txt(path);if(!xml)throw new Error('تعذر قراءة ورقة العمل الأولى');
  const shared=[],ss=txt('xl/sharedStrings.xml');
  if(ss)for(const m of ss.matchAll(/<(?:\w+:)?si\b[^>]*>([\s\S]*?)<\/(?:\w+:)?si>/gi)){
    const ts=[...m[1].matchAll(/<(?:\w+:)?t\b[^>]*>([\s\S]*?)<\/(?:\w+:)?t>/gi)].map(x=>xmlUnescape(x[1]));shared.push(ts.join(''));
  }
  const rows=[];
  for(const rm of xml.matchAll(/<(?:\w+:)?row\b[^>]*>([\s\S]*?)<\/(?:\w+:)?row>/gi)){
    const arr=[];
    for(const cm of rm[1].matchAll(/<(?:\w+:)?c\b([^>]*)>([\s\S]*?)<\/(?:\w+:)?c>/gi)){
      const attrs=cm[1],body=cm[2],ref=(attrs.match(/\br="([A-Z]+)\d+"/i)||[])[1]||'A',idx=colIndex(ref),type=(attrs.match(/\bt="([^"]+)"/i)||[])[1]||'';
      const v=(body.match(/<(?:\w+:)?v\b[^>]*>([\s\S]*?)<\/(?:\w+:)?v>/i)||[])[1]??'',inline=(body.match(/<(?:\w+:)?t\b[^>]*>([\s\S]*?)<\/(?:\w+:)?t>/i)||[])[1];
      let val=type==='s'?shared[Number(v)]??'':(type==='inlineStr'?xmlUnescape(inline||''):xmlUnescape(v));arr[idx]=val;
    }
    for(let i=0;i<arr.length;i++)if(arr[i]==null)arr[i]='';rows.push(arr);
  }
  return rows;
}
function xmlUnescape(s){return String(s||'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'")}
function colIndex(s){let n=0;for(const c of s.toUpperCase())n=n*26+c.charCodeAt(0)-64;return n-1}
async function unzipEntries(buffer){const u=new Uint8Array(buffer),dv=new DataView(buffer);let eocd=-1;for(let i=u.length-22;i>=Math.max(0,u.length-65557);i--){if(dv.getUint32(i,true)===0x06054b50){eocd=i;break}}if(eocd<0)throw new Error('ZIP غير صالح');const count=dv.getUint16(eocd+10,true),cdOff=dv.getUint32(eocd+16,true),files={};let p=cdOff;for(let i=0;i<count;i++){if(dv.getUint32(p,true)!==0x02014b50)break;const method=dv.getUint16(p+10,true),comp=dv.getUint32(p+20,true),nameLen=dv.getUint16(p+28,true),extraLen=dv.getUint16(p+30,true),commentLen=dv.getUint16(p+32,true),localOff=dv.getUint32(p+42,true),name=new TextDecoder().decode(u.slice(p+46,p+46+nameLen));if(dv.getUint32(localOff,true)===0x04034b50){const ln=dv.getUint16(localOff+26,true),le=dv.getUint16(localOff+28,true),start=localOff+30+ln+le,raw=u.slice(start,start+comp);if(method===0)files[name]=raw;else if(method===8){if(typeof DecompressionStream==='undefined')throw new Error('المتصفح لا يدعم فك XLSX');const ds=new DecompressionStream('deflate-raw'),stream=new Blob([raw]).stream().pipeThrough(ds);files[name]=new Uint8Array(await new Response(stream).arrayBuffer())}}p+=46+nameLen+extraLen+commentLen}return files}

function csvEscape(v){const s=String(v??'');return /[",\n;]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function downloadCSV(name,rows){const text='\uFEFF'+rows.map(r=>r.map(csvEscape).join(',')).join('\r\n');downloadBlob(name,text,'text/csv;charset=utf-8')}
function downloadBlob(name,data,type){const blob=new Blob([data],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function downloadStatic(href,name){const a=document.createElement('a');a.href=href;a.download=name||'';document.body.appendChild(a);a.click();a.remove()}
function exportLoansCSV(data,name){downloadCSV(`${name}-${todayISO()}.csv`,[['الطالب','كود الطالب','الكتاب','باركود الكتاب','تاريخ الاستعارة','تاريخ الاستحقاق','تاريخ الإرجاع','الحالة','التجديدات','المحطة'],...data.map(l=>[l.student,l.studentCode,l.book,l.bookCode,l.loanDateISO,l.dueDateISO,l.returnedDateISO||'',l.status,l.renewalsUsed||0,stationName(l.stationId)])])}
function exportActivityCSV(){downloadCSV(`activity-${todayISO()}.csv`,[['الوقت','النوع','التفاصيل','المستخدم','المحطة'],...state.activityLogs.map(x=>[x.atISO,x.type,x.message,x.user,stationName(x.stationId)])])}
function exportBackup(){downloadBlob(`bilal-smart-library-v05-backup-${todayISO()}.json`,JSON.stringify({version:VERSION,exportedAt:nowISO(),...serializableState()},null,2),'application/json')}
function importBackup(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!Array.isArray(x.students)||!Array.isArray(x.books))throw new Error();replaceState(x);logActivity('استعادة','تمت استعادة نسخة احتياطية');saveState();render('settings');toast('تمت الاستعادة بنجاح')}catch(e){toast('ملف النسخة الاحتياطية غير صالح')}};r.readAsText(file,'utf-8')}

const code39Patterns={'0':'nnnwwnwnn','1':'wnnwnnnnw','2':'nnwwnnnnw','3':'wnwwnnnnn','4':'nnnwwnnnw','5':'wnnwwnnnn','6':'nnwwwnnnn','7':'nnnwnnwnw','8':'wnnwnnwnn','9':'nnwwnnwnn','A':'wnnnnwnnw','B':'nnwnnwnnw','C':'wnwnnwnnn','D':'nnnnwwnnw','E':'wnnnwwnnn','F':'nnwnwwnnn','G':'nnnnnwwnw','H':'wnnnnwwnn','I':'nnwnnwwnn','J':'nnnnwwwnn','K':'wnnnnnnww','L':'nnwnnnnww','M':'wnwnnnnwn','N':'nnnnwnnww','O':'wnnnwnnwn','P':'nnwnwnnwn','Q':'nnnnnnwww','R':'wnnnnnwwn','S':'nnwnnnwwn','T':'nnnnwnwwn','U':'wwnnnnnnw','V':'nwwnnnnnw','W':'wwwnnnnnn','X':'nwnnwnnnw','Y':'wwnnwnnnn','Z':'nwwnwnnnn','-':'nwnnnnwnw','.':'wwnnnnwnn',' ':'nwwnnnwnn','$':'nwnwnwnnn','/':'nwnwnnnwn','+':'nwnnnwnwn','%':'nnnwnwnwn','*':'nwnnwnwnn'};
function barcodeSVG(value,height=58){const text=String(value).toUpperCase().replace(/[^0-9A-Z. \-$/+%]/g,''),seq='*'+text+'*',narrow=2,wide=5,gap=2,quiet=12;let x=quiet,rects='';for(const ch of seq){const p=code39Patterns[ch]||code39Patterns['-'];for(let i=0;i<p.length;i++){const w=p[i]==='w'?wide:narrow;if(i%2===0)rects+=`<rect x="${x}" y="0" width="${w}" height="${height}"/>`;x+=w}x+=gap}return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${x+quiet} ${height}" preserveAspectRatio="none"><g fill="#000">${rects}</g></svg>`}
function printWindow(title,html){const w=window.open('','_blank','width=1000,height=760');if(!w){toast('اسمح بالنوافذ المنبثقة للطباعة');return}w.document.write(`<!doctype html><html dir="rtl"><head><meta charset="utf-8"><title>${esc(title)}</title><style>@page{size:A4;margin:10mm}*{box-sizing:border-box}body{font-family:Arial,Tahoma;margin:0}.sheet{display:grid;grid-template-columns:repeat(2,1fr);gap:8mm}.student-card-print{border:1px solid #ccd5dd;border-radius:16px;padding:14px;height:78mm;display:flex;flex-direction:column;justify-content:space-between;page-break-inside:avoid}.book-label{border:1px solid #bbb;border-radius:10px;padding:9px;height:43mm;page-break-inside:avoid}.top{display:flex;gap:10px;align-items:center}.plogo{width:46px;height:46px;object-fit:contain}.mark{width:44px;height:44px;border-radius:12px;background:#12384a;color:white;display:grid;place-items:center;font-weight:bold}.school,.small{font-size:11px;color:#666}.name{font-size:18px;font-weight:800;margin:10px 0 4px}.meta{font-size:12px;color:#555}.barcode{height:18mm;margin-top:8px}.barcode svg{width:100%;height:100%}.code{text-align:center;font:700 12px monospace;letter-spacing:1px}.book-label .name{font-size:14px}.book-label .barcode{height:13mm}@media print{button{display:none}}</style></head><body><div class="sheet">${html}</div><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);w.document.close()}
function studentCardHTML(s){return `<div class="student-card-print"><div><div class="top">${state.config.logo?`<img class="plogo" src="${state.config.logo}">`:'<div class="mark">م</div>'}<div><b>${esc(state.config.schoolName)}</b><div class="school">${esc(state.config.siteName)}</div></div></div><div class="name">${esc(s.name)}</div><div class="meta">الصف: ${esc(s.grade)} — الشعبة: ${esc(s.section)}</div></div><div><div class="barcode">${barcodeSVG(s.code)}</div><div class="code">${esc(s.code)}</div></div></div>`}
function bookLabelHTML(b){return `<div class="book-label"><div class="top">${state.config.logo?`<img class="plogo" src="${state.config.logo}">`:'<div class="mark">م</div>'}<div><b>${esc(state.config.schoolName)}</b><div class="small">${esc(state.config.siteName)}</div></div></div><div class="name">${esc(b.title)}</div><div class="small">${esc(b.category)} • الرف ${esc(b.shelf)} • ${esc(b.accession||'')}</div><div class="barcode">${barcodeSVG(b.code,50)}</div><div class="code">${esc(b.code)}</div></div>`}
function printStudentCard(code){const s=state.students.find(x=>x.code===code);if(s)printWindow('بطاقة '+s.name,studentCardHTML(s))} function printAllStudentCards(){printWindow('بطاقات الطلاب',state.students.map(studentCardHTML).join(''))} function printBookLabel(code){const b=state.books.find(x=>x.code===code);if(b)printWindow('ملصق '+b.title,bookLabelHTML(b))} function printAllBookLabels(){printWindow('ملصقات الكتب',state.books.map(bookLabelHTML).join(''))}

