async function cloudTransaction(action,payload={}){try{const {data,error}=await sb.functions.invoke('library-transaction',{body:{action,schoolId:CLOUD.schoolId,...payload}});if(error)return {ok:false,message:error.message};return data}catch(e){return {ok:false,message:'تعذر الاتصال بخدمة المكتبة السحابية'}}}
async function loadCloudUsers(){if(currentUser?.role!=='admin'){state.users=currentUser?[{...currentUser}]:[];return}const {data,error}=await sb.functions.invoke('library-users',{body:{action:'list',schoolId:CLOUD.schoolId}});if(!error&&data?.ok)state.users=(data.users||[]).map(u=>({id:u.user_id,username:u.email,displayName:u.full_name,role:u.role,active:u.active}))}
const dbBookStatusToAr=s=>({available:'متاح',on_loan:'مستعار',reserved:'محجوز',lost:'مفقود',maintenance:'موقوف'}[s]||s);
const arBookStatusToDb=s=>({'متاح':'available','مستعار':'on_loan','محجوز':'reserved','مفقود':'lost','موقوف':'maintenance'}[s]||'available');
async function loadCloudState(showError=true,preserveKiosk=false){
 try{
  const {data:{user}}=await sb.auth.getUser();if(!user)return false;authUser=user;
  const {data:mem,error:me}=await sb.from('memberships').select('user_id,school_id,full_name,role,active').eq('user_id',user.id).eq('school_id',CLOUD.schoolId).maybeSingle();if(me||!mem?.active)return false;
  currentUser={id:user.id,username:user.email||'',displayName:mem.full_name,role:mem.role,active:true};
  const kioskState=preserveKiosk?state.kiosk:{step:'student',student:null,lastBook:null,lastLoanDueISO:null};
  const [{data:school},{data:settings},{data:stations}]=await Promise.all([sb.from('schools').select('*').eq('id',CLOUD.schoolId).single(),sb.from('library_settings').select('*').eq('school_id',CLOUD.schoolId).single(),sb.from('stations').select('*').eq('school_id',CLOUD.schoolId).order('created_at')]);
  state.config={...state.config,siteName:school?.site_name||'Bilal Smart Library',schoolName:school?.name||'مدرسة بلال بن رباح النموذجية للبنين',logo:school?.logo_url||'',maxBooks:settings?.max_books||3,loanDays:settings?.loan_days||14,renewals:settings?.max_renewals??1,preventOverdue:settings?.block_if_overdue??true,reservationDays:settings?.reservation_hold_days||3,autoClose:true,sessionSeconds:settings?.session_timeout_seconds||12};
  state.stations=(stations||[]).map(x=>({dbId:x.id,id:x.station_code,name:x.name,location:x.location||'',type:'self_checkout',readerMode:x.scanner_mode||'hybrid',enabled:x.active}));if(!state.stations.length)state.stations=deepClone(defaults.stations);if(!state.stations.some(x=>x.id===state.config.currentStationId))state.config.currentStationId=state.stations[0]?.id||'KIOSK-01';
  if(mem.role==='kiosk'){state.students=[];state.books=[];state.loans=[];state.reservations=[];state.activityLogs=[];state.kiosk=kioskState;await loadCloudUsers();applyBranding();persistLocal();remoteMode=true;return true}
  const [sr,br,cr,lr,rr,ar]=await Promise.all([sb.from('students').select('*').eq('school_id',CLOUD.schoolId).order('full_name'),sb.from('books').select('*').eq('school_id',CLOUD.schoolId),sb.from('book_copies').select('*').eq('school_id',CLOUD.schoolId),sb.from('loan_details').select('*').eq('school_id',CLOUD.schoolId).order('loaned_at',{ascending:false}),sb.from('reservations').select('*').eq('school_id',CLOUD.schoolId).order('requested_at',{ascending:false}),sb.from('activity_logs').select('*').eq('school_id',CLOUD.schoolId).order('created_at',{ascending:false}).limit(500)]);
  for(const r of [sr,br,cr,lr,rr,ar])if(r.error)throw r.error;
  const students=sr.data||[],books=br.data||[],copies=cr.data||[];const sm=new Map(students.map(x=>[x.id,x])),bm=new Map(books.map(x=>[x.id,x])),cm=new Map(copies.map(x=>[x.id,x]));
  state.students=students.map(x=>({dbId:x.id,code:x.student_code,personalId:x.personal_number||'',name:x.full_name,grade:x.grade||'',section:x.section||'',status:x.active?'نشط':'موقوف',rfidTag:x.rfid_uid||''}));
  state.books=copies.map(c=>{const b=bm.get(c.book_id)||{};return {dbBookId:c.book_id,dbCopyId:c.id,code:c.copy_code,accession:c.accession_number||'',isbn:b.isbn||'',title:b.title||'كتاب',author:b.author||'',category:b.category||'غير مصنف',publisher:b.publisher||'',year:b.publication_year||'',shelf:b.shelf||'',status:dbBookStatusToAr(c.status),rfidTag:c.rfid_uid||'',callNumber:b.call_number||''}});
  state.loans=(lr.data||[]).map(l=>({id:l.loan_id,studentCode:l.student_code,student:l.student_name,bookCode:l.copy_code,book:l.title,loanDateISO:(l.loaned_at||'').slice(0,10),dueDateISO:(l.due_at||'').slice(0,10),returnedDateISO:l.returned_at?(l.returned_at||'').slice(0,10):null,status:l.returned_at?'تم الإرجاع':(new Date(l.due_at)<new Date()?'متأخر':'مستعار'),renewalsUsed:l.renewal_count||0,stationId:(state.stations.find(s=>s.name===l.checkout_station_name)?.id)||'',createdISO:l.loaned_at}));
  state.reservations=(rr.data||[]).map(r=>{const stu=sm.get(r.student_id),book=bm.get(r.book_id),ready=cm.get(r.ready_copy_id);const first=copies.find(c=>c.book_id===r.book_id);return {id:r.id,studentCode:stu?.student_code||'',bookCode:ready?.copy_code||first?.copy_code||'',dbBookId:r.book_id,status:['queued','ready'].includes(r.status)?'نشط':r.status==='fulfilled'?'مكتمل':r.status==='cancelled'?'ملغي':'منتهي',createdISO:r.requested_at,expiresISO:r.expires_at,ready:r.status==='ready',bookTitle:book?.title||''}});
  state.activityLogs=(ar.data||[]).map(x=>({id:x.id,type:x.action,message:x.details?.message||x.action,meta:x.details||{},stationId:state.stations.find(s=>s.dbId===x.station_id)?.id||'',user:'cloud',atISO:x.created_at}));state.kiosk=kioskState;await loadCloudUsers();refreshDerivedState();persistLocal();applyBranding();remoteMode=true;cloudLastLoad=Date.now();return true;
 }catch(e){console.error('cloud load',e);if(showError)toast('تعذر تحميل البيانات السحابية');return false}
}
async function cloudSyncMasterData(){if(!remoteMode||cloudSyncBusy||!currentUser||!['admin','librarian'].includes(currentUser.role))return;cloudSyncBusy=true;try{
 if(currentUser.role==='admin'){
  await sb.from('schools').update({name:state.config.schoolName,site_name:state.config.siteName,logo_url:state.config.logo||null}).eq('id',CLOUD.schoolId);
  await sb.from('library_settings').update({loan_days:state.config.loanDays,max_books:state.config.maxBooks,max_renewals:state.config.renewals,block_if_overdue:state.config.preventOverdue,session_timeout_seconds:state.config.sessionSeconds,reservation_hold_days:state.config.reservationDays}).eq('school_id',CLOUD.schoolId);
  const sts=state.stations.map(x=>({school_id:CLOUD.schoolId,station_code:x.id,name:x.name,location:x.location||null,scanner_mode:x.readerMode||'hybrid',active:x.enabled!==false}));if(sts.length)await sb.from('stations').upsert(sts,{onConflict:'school_id,station_code'});
 }
 const stud=state.students.map(x=>({school_id:CLOUD.schoolId,student_code:x.code,personal_number:x.personalId||null,full_name:x.name,grade:x.grade||null,section:x.section||null,barcode:x.code,rfid_uid:x.rfidTag||null,active:x.status==='نشط'}));if(stud.length)await sb.from('students').upsert(stud,{onConflict:'school_id,student_code'});
 for(const b of state.books){
  let bookId=b.dbBookId;if(bookId){await sb.from('books').update({title:b.title,author:b.author||null,isbn:b.isbn||null,category:b.category||null,publisher:b.publisher||null,publication_year:b.year?Number(b.year):null,call_number:b.callNumber||b.code,shelf:b.shelf||null,active:b.status!=='موقوف'}).eq('id',bookId).eq('school_id',CLOUD.schoolId)}else{const {data:nb,error}=await sb.from('books').insert({school_id:CLOUD.schoolId,title:b.title,author:b.author||null,isbn:b.isbn||null,category:b.category||null,publisher:b.publisher||null,publication_year:b.year?Number(b.year):null,call_number:b.code,shelf:b.shelf||null,active:true}).select('id').single();if(error)throw error;bookId=nb.id;b.dbBookId=bookId}
  const copy={school_id:CLOUD.schoolId,book_id:bookId,copy_code:b.code,accession_number:b.accession||null,barcode:b.code,rfid_uid:b.rfidTag||null};if(b.dbCopyId){await sb.from('book_copies').update(copy).eq('id',b.dbCopyId)}else{const {data:nc,error}=await sb.from('book_copies').insert({...copy,status:'available'}).select('id').single();if(error)throw error;b.dbCopyId=nc.id}
 }
 }catch(e){console.error('cloud sync',e);toast('تعذر حفظ بعض التغييرات سحابيًا')}finally{cloudSyncBusy=false}}
async function cloudImportStudents(items){const rows=items.map(x=>({school_id:CLOUD.schoolId,student_code:x.code,personal_number:x.personalId||null,full_name:x.name,grade:x.grade||null,section:x.section||null,barcode:x.code,rfid_uid:x.rfidTag||null,active:true}));const {error}=await sb.from('students').upsert(rows,{onConflict:'school_id,student_code'});if(error){toast('تعذر استيراد الطلاب: '+error.message);return false}return true}
async function cloudImportBooks(items){try{const catalog=items.map(x=>({school_id:CLOUD.schoolId,title:x.title,author:x.author||null,isbn:x.isbn||null,category:x.category||null,publisher:x.publisher||null,publication_year:x.year?Number(x.year):null,call_number:x.code,shelf:x.shelf||null,active:true}));const {data:books,error}=await sb.from('books').insert(catalog).select('id,call_number');if(error)throw error;const map=new Map((books||[]).map(b=>[b.call_number,b.id]));const copies=items.map(x=>({school_id:CLOUD.schoolId,book_id:map.get(x.code),copy_code:x.code,accession_number:x.accession||null,barcode:x.code,rfid_uid:x.rfidTag||null,status:'available'}));const {error:ce}=await sb.from('book_copies').insert(copies);if(ce)throw ce;return true}catch(e){console.error(e);toast('تعذر استيراد الكتب: '+e.message);return false}}
async function pushFullState(){await cloudSyncMasterData()}
function startRemotePolling(){clearInterval(remotePoller);remotePoller=setInterval(async()=>{if(document.hidden||document.querySelector('#modalBackdrop:not(.hidden)')||state.kiosk?.student)return;if(Date.now()-cloudLastLoad<4500)return;const view=currentView;const ok=await loadCloudState(false,true);if(ok&&!$('#appView').classList.contains('hidden'))render(view)},6000)}
async function remoteTransaction(path,payload){const action=path.includes('loan')?'checkout':path.includes('return')?'return':path.includes('renew')?'renew':path.includes('cancel-reservation')?'cancel_reservation':path.includes('reserve')?'reserve':'';return cloudTransaction(action,payload)}
async function detectRemote(){const {data}=await sb.auth.getSession();if(!data.session){remoteMode=false;return false}authUser=data.session.user;const ok=await loadCloudState(false,true);remoteMode=ok;if(ok)startRemotePolling();return ok}
async function bootstrap(){state.config.siteName='Bilal Smart Library';state.config.schoolName='مدرسة بلال بن رباح النموذجية للبنين';applyBranding();$('#todayChip').textContent=new Intl.DateTimeFormat('ar-QA',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date());const ok=await detectRemote();if(ok&&currentUser)showApp();else{$('#appView').classList.add('hidden');$('#loginView').classList.remove('hidden')}updateSidebarBadges()}

