let realtimeChannelV06=null,realtimeDebounceV06=null,heartbeatTimerV06=null,scanBusyV06=false;
let scannerLastCodeV065='',scannerLastAtV065=0;
function numericBarcodeV06(prefix='20'){
  let value='';
  do{value=prefix+String(Date.now()).slice(-10)+String(Math.floor(Math.random()*100)).padStart(2,'0')}while(state.students.some(x=>x.barcode===value)||state.books.some(x=>x.barcode===value));
  return value;
}
function bookStatusArV06(s){return ({available:'متاح',on_loan:'مستعار',reserved:'محجوز',lost:'مفقود',damaged:'تالف',maintenance:'صيانة'})[s]||s}
function bookStatusDbV06(s){return ({'متاح':'available','مستعار':'on_loan','محجوز':'reserved','مفقود':'lost','تالف':'damaged','صيانة':'maintenance','موقوف':'maintenance'})[s]||'available'}
function stationTypeLabelV06(t){return ({self_checkout:'استعارة ذاتية',staff_desk:'مكتب موظف',self_return:'إرجاع ذاتي',hybrid:'استعارة وإرجاع ذاتي'})[t]||t}
function isOnlineV06(st){if(!st.lastSeen)return false;return Date.now()-new Date(st.lastSeen).getTime()<90000}
function playSuccessSoundV06(){if(state.config.successSound===false)return;try{const AC=window.AudioContext||window.webkitAudioContext;const c=new AC(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=880;g.gain.setValueAtTime(.06,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.16);o.start();o.stop(c.currentTime+.17)}catch(e){}}

function applyPermissions(){
  $$('.admin-only').forEach(x=>x.style.display=currentUser?.role==='admin'?'flex':'none');
  const chip=$('#topUserName');if(chip)chip.textContent=currentUser?.displayName||'محطة ذاتية';
  const role=$('#topUserRole');if(role)role.textContent=currentUser?ROLE_LABELS[currentUser.role]:'وضع الطالب';
  const av=document.querySelector('#userChip .avatar');if(av)av.textContent=(currentUser?.displayName||'ط')[0];
}
function ensureKioskExitButtonV06(){
  let b=document.getElementById('kioskSecureExit'),sw=document.getElementById('kioskModeSwitch');
  if(currentUser?.role==='kiosk'){
    if(!b){b=document.createElement('button');b.id='kioskSecureExit';b.className='kiosk-secure-exit';b.textContent='العودة للإدارة';b.onclick=requestKioskExitV06;document.body.appendChild(b)}
    const st=currentStation();
    if(st.type==='hybrid'){
      if(!sw){sw=document.createElement('button');sw.id='kioskModeSwitch';sw.className='kiosk-mode-switch';sw.onclick=()=>{kioskHybridViewV06=kioskHybridViewV06==='checkout'?'return':'checkout';render(kioskHybridViewV06==='return'?'returns':'kiosk');ensureKioskExitButtonV06()};document.body.appendChild(sw)}
      sw.textContent=kioskHybridViewV06==='checkout'?'التحويل إلى الإرجاع':'التحويل إلى الاستعارة';
    }else sw?.remove();
  }else{b?.remove();sw?.remove()}
}
async function requestKioskExitV06(){
  let configured=false;
  try{
    const {data,error}=await sb.rpc('kiosk_exit_pin_status',{p_school_id:CLOUD.schoolId});
    if(error)throw error;
    configured=!!data;
  }catch(e){console.error('kiosk pin status',e);toast('تعذر التحقق من إعداد حماية المحطة');return}

  if(!configured){
    openModal('العودة إلى شاشة الدخول','لم يتم تعيين رمز خروج للمحطة حتى الآن. سيتم تسجيل خروج حساب المحطة فقط، وبعدها يمكن للمدير تسجيل الدخول بحسابه.',`<div class="info-banner"><b>تنبيه:</b> لا يوجد PIN خروج مفعّل لهذه المحطة.</div><div class="modal-actions"><button class="btn ghost" id="cancelKioskExitV061">البقاء في المحطة</button><button class="btn primary" id="confirmKioskExitV061">تسجيل الخروج والعودة للإدارة</button></div>`);
    $('#cancelKioskExitV061').onclick=closeModal;
    $('#confirmKioskExitV061').onclick=async()=>{closeModal();await showLogin()};
    return;
  }

  openModal('العودة إلى الإدارة','أدخل رمز خروج المحطة الذي عيّنه مدير النظام.',`<div class="field"><label>رمز الخروج</label><input id="kioskExitPinInputV061" type="password" inputmode="numeric" maxlength="8" autocomplete="off" placeholder="••••"></div><div id="kioskExitPinErrorV061" class="field-error"></div><div class="modal-actions"><button class="btn ghost" id="cancelKioskPinV061">إلغاء</button><button class="btn primary" id="verifyKioskPinV061">تحقق وعودة للإدارة</button></div>`);
  const inp=$('#kioskExitPinInputV061'),err=$('#kioskExitPinErrorV061');
  $('#cancelKioskPinV061').onclick=closeModal;
  const verify=async()=>{
    const pin=inp.value.trim();
    if(!/^\d{4,8}$/.test(pin)){err.textContent='أدخل رمزًا من 4 إلى 8 أرقام.';inp.focus();return}
    const btn=$('#verifyKioskPinV061');btn.disabled=true;btn.textContent='جارٍ التحقق…';err.textContent='';
    const r=await cloudTransaction('verify_exit_pin',{pin});
    if(r?.ok&&r.valid){closeModal();await showLogin();return}
    btn.disabled=false;btn.textContent='تحقق وعودة للإدارة';err.textContent=r?.message||(r?.ok?'رمز الخروج غير صحيح':'تعذر التحقق من الرمز');inp.select();
  };
  $('#verifyKioskPinV061').onclick=verify;inp.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();verify()}};setTimeout(()=>inp.focus(),60);
}
function showApp(){
  clearKioskTimer();$('#loginView').classList.add('hidden');$('#appView').classList.remove('hidden');
  const kioskOnly=currentUser?.role==='kiosk';document.body.classList.toggle('kiosk-mode',kioskOnly);ensureKioskExitButtonV06();applyPermissions();
  if(kioskOnly){const st=currentStation();render(st.type==='self_return'?'returns':st.type==='hybrid'&&kioskHybridViewV06==='return'?'returns':'kiosk');ensureKioskExitButtonV06()}else render('dashboard');
}
async function showLogin(){
  clearKioskTimer();detachGlobalScanner();document.body.classList.remove('kiosk-mode','kiosk-guest');document.getElementById('kioskSecureExit')?.remove();document.getElementById('kioskModeSwitch')?.remove();
  try{if(realtimeChannelV06)await sb.removeChannel(realtimeChannelV06)}catch{};realtimeChannelV06=null;clearInterval(heartbeatTimerV06);clearInterval(remotePoller);
  try{await sb?.auth.signOut()}catch{}currentUser=null;authUser=null;remoteMode=false;$('#appView').classList.add('hidden');$('#loginView').classList.remove('hidden');updateModePill();
}

function attachGlobalScanner(input,callback){
  let buffer='',last=0,autoTimer=null;
  const kioskCapture=()=>currentView==='kiosk'&&input?.id==='kioskScan'&&(currentUser?.role==='kiosk'||guestKioskModeV067||document.body.classList.contains('kiosk-mode'));
  const refocus=()=>{const target=$('#kioskScan')||input;if(currentView==='kiosk'&&target?.isConnected&&!document.querySelector('#modalBackdrop:not(.hidden)')){try{target.focus({preventScroll:true})}catch{target.focus()}}};
  const clearAuto=()=>{if(autoTimer){clearTimeout(autoTimer);autoTimer=null}};
  const submit=async()=>{
    clearAuto();
    const code=String(buffer||input?.value||'').trim();
    if(!code){refocus();return}
    const now=Date.now();buffer='';if(input)input.value='';
    if(scanBusyV06){refocus();return}
    if(code===scannerLastCodeV065&&now-scannerLastAtV065<700){refocus();return}
    scannerLastCodeV065=code;scannerLastAtV065=now;scanBusyV06=true;
    try{await callback(code)}finally{setTimeout(()=>{scanBusyV06=false;refocus()},100)}
  };
  scannerHandler=e=>{
    const isKiosk=kioskCapture();
    if(document.querySelector('#modalBackdrop:not(.hidden)'))return;
    if(e.ctrlKey||e.altKey||e.metaKey)return;
    if(!isKiosk){
      if(document.activeElement?.matches('textarea,select')&&document.activeElement!==input)return;
      if(document.activeElement?.matches('input')&&document.activeElement!==input)return;
    }
    const now=Date.now();
    if(now-last>250)buffer='';last=now;
    if(e.key==='Enter'||e.key==='Tab'){
      if(isKiosk){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation()}
      submit().catch(console.error);return;
    }
    if(e.key.length===1){
      if(isKiosk){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation()}
      buffer+=e.key;
      if(input)input.value='';
      clearAuto();
      // USB/HID scanners type the whole code as a fast burst. Submit automatically
      // after a short quiet gap, so Enter is never required.
      if(isKiosk&&buffer.length>=4)autoTimer=setTimeout(()=>submit().catch(console.error),90);
    }
  };
  document.addEventListener('keydown',scannerHandler,true);
  setTimeout(refocus,0);
}
function detachGlobalScanner(){if(scannerHandler){document.removeEventListener('keydown',scannerHandler,true);scannerHandler=null}scanBusyV06=false}

async function handleScan(code){
  touchKioskTimer();
  if(!state.kiosk.student){
    if(remoteMode){const r=await cloudTransaction('student_lookup',{studentCode:String(code).trim()});if(!r?.ok){scanMsg(r?.message||'لم يتم العثور على الطالب',false);return}const s={code:r.student.code,name:r.student.name,grade:r.student.grade||'',section:r.student.section||'',status:r.student.active?'نشط':'موقوف',activeLoans:r.student.activeLoans||0,overdue:r.student.overdue||0};if(s.status!=='نشط'){scanMsg('حساب الطالب موقوف',false);return}state.kiosk.student=s;state.kiosk.step='book';render('kiosk');return}
    const s=resolveStudent(code);if(!s){scanMsg('لم يتم العثور على الطالب',false);return}state.kiosk.student=s;state.kiosk.step='book';render('kiosk');return;
  }
  const studentName=state.kiosk.student.name,studentCode=state.kiosk.student.code,bookCode=String(code).trim();
  if(remoteMode){
    const br=await cloudTransaction('book_lookup',{bookCode});if(!br?.ok){scanMsg(br?.message||'لم يتم العثور على الكتاب',false);return}
    const result=await borrowBook(studentCode,br.book.copyCode);
    if(result.ok){clearKioskTimer();playSuccessSoundV06();const bookTitle=br.book.title||'الكتاب';resetKiosk();toast(`✓ تمت استعارة «${bookTitle}» للطالب ${studentName}`)}else scanMsg(result.message,false);return;
  }
  const b=resolveBook(bookCode);if(!b){scanMsg('لم يتم العثور على الكتاب',false);return}
  const result=await borrowBook(studentCode,b.code);
  if(result.ok){clearKioskTimer();playSuccessSoundV06();const bookTitle=b.title||'الكتاب';resetKiosk();toast(`✓ تمت استعارة «${bookTitle}» للطالب ${studentName}`)}else scanMsg(result.message,false)
}
async function returnBook(identifier,show=true){
  if(remoteMode){const res=await cloudTransaction('return',{bookCode:String(identifier).trim(),stationCode:currentStation().id});if(res?.ok){playSuccessSoundV06();await loadCloudState(false,true);if(show){toast('تم تسجيل الإرجاع بنجاح');render(currentView)}return {ok:true}}if(show)toast(res?.message||'تعذر الإرجاع');return {ok:false}}
  const b=resolveBook(identifier);if(!b){if(show)scanMsg('الكتاب غير معروف',false);return {ok:false}}const loan=state.loans.find(l=>l.bookCode===b.code&&['مستعار','متأخر'].includes(l.status));if(!loan){if(show)scanMsg('لا توجد استعارة نشطة لهذا الكتاب',false);return {ok:false}}return returnLoanById(loan.id,show)
}

