async function saveStudentModal(original){const name=$('#mStudentName').value.trim(),pid=$('#mStudentPid').value.trim(),grade=$('#mStudentGrade').value.trim(),section=$('#mStudentSection').value.trim(),code=$('#mStudentCode').value.trim().toUpperCase(),barcode=$('#mStudentBarcode').value.trim(),rfid=$('#mStudentRfid').value.trim();if(!name||!code||!barcode){toast('الاسم والكود والباركود مطلوبة');return}const old=original?state.students.find(s=>s.code===original):null;if(state.students.some(s=>s.code===code&&s!==old)){toast('كود الطالب مستخدم');return}if(state.students.some(s=>s.barcode===barcode&&s!==old)){toast('الباركود مستخدم لطالب آخر');return}if(pid&&state.students.some(s=>s.personalId===pid&&s!==old)){toast('الرقم الشخصي مستخدم لطالب آخر');return}if(rfid&&state.students.some(s=>s.rfidTag===rfid&&s!==old)){toast('RFID مرتبط بطالب آخر');return}
 if(remoteMode){const payload={school_id:CLOUD.schoolId,student_code:code,personal_number:pid||null,full_name:name,grade:grade||null,section:section||null,barcode,rfid_uid:rfid||null,active:old?old.status==='نشط':true};let q;if(old?.dbId)q=sb.from('students').update(payload).eq('id',old.dbId);else q=sb.from('students').insert(payload);const {error}=await q;if(error){toast('تعذر حفظ الطالب: '+error.message);return}logActivity(old?'تعديل طالب':'إضافة طالب',name,{studentCode:code});await loadCloudState(false,true);closeModal();render('students');toast('تم حفظ الطالب');return}
 if(old)Object.assign(old,{name,personalId:pid,grade,section,code,barcode,rfidTag:rfid});else state.students.push({code,barcode,name,personalId:pid,grade,section,status:'نشط',rfidTag:rfid});saveState(false);closeModal();render('students')}
async function toggleStudentStatus(code){const s=state.students.find(x=>x.code===code);if(!s)return;if(s.status==='نشط'&&state.loans.some(l=>l.studentCode===code&&['مستعار','متأخر'].includes(l.status))){toast('لا يمكن إيقاف طالب لديه استعارات نشطة');return}const active=s.status!=='نشط';if(remoteMode&&s.dbId){const {error}=await sb.from('students').update({active}).eq('id',s.dbId);if(error){toast(error.message);return}await loadCloudState(false,true)}else{s.status=active?'نشط':'موقوف';saveState(false)}render('students')}

function catalogGroupsV06(list=state.books){const m=new Map();for(const c of list){const k=c.dbBookId||`local:${c.isbn||c.title+'|'+c.author}`;if(!m.has(k))m.set(k,{id:k,dbBookId:c.dbBookId,title:c.title,author:c.author,isbn:c.isbn,category:c.category,publisher:c.publisher,year:c.year,shelf:c.shelf,callNumber:c.callNumber,copies:[]});m.get(k).copies.push(c)}return [...m.values()]}
function catalogTableV06(groups){return `<div class="table-scroll"><table class="data-table"><thead><tr><th>العنوان</th><th>المؤلف / التصنيف</th><th>النسخ</th><th>متاح</th><th>مستعار</th><th>محجوز</th><th>إجراء</th></tr></thead><tbody>${groups.map(g=>`<tr><td><button class="link-btn" onclick="openCatalogRecordV06('${esc(g.id)}')">${esc(g.title)}</button><br><small>${esc(g.isbn||g.callNumber||'')}</small></td><td>${esc(g.author||'—')}<br><small>${esc(g.category||'—')}</small></td><td><b>${g.copies.length}</b></td><td>${g.copies.filter(x=>x.status==='متاح').length}</td><td>${g.copies.filter(x=>x.status==='مستعار').length}</td><td>${g.copies.filter(x=>x.status==='محجوز').length}</td><td><div class="row-actions"><button class="btn ghost btn-sm" onclick="openCatalogRecordV06('${esc(g.id)}')">السجل</button><button class="btn primary btn-sm" onclick="openBookModal(null,'${esc(g.id)}')">+ نسخة</button></div></td></tr>`).join('')}</tbody></table></div>`}
function books(){const groups=catalogGroupsV06();return `<div class="section-title"><div><h2>الكتب والنسخ</h2><p>فهرس موحد: عنوان واحد يمكن أن يحتوي على عدة نسخ، ولكل نسخة باركود مستقل.</p></div><div class="toolbar-wrap"><label class="btn secondary file-btn">استيراد Excel/CSV<input id="bookImportFile" type="file" accept=".xlsx,.csv,.txt" hidden></label><button class="btn ghost" id="bookTemplateBtn">قالب Excel/CSV</button><button class="btn secondary" id="printAllBooks">طباعة الملصقات</button><button class="btn primary" id="addBookBtn">+ عنوان ونسخة</button></div></div><div class="info-banner"><b>فهرسة صحيحة:</b> عند وجود ISBN متطابق أو عنوان ومؤلف متطابقين، تُضاف النسخة الجديدة تحت نفس سجل الكتاب بدل إنشاء عنوان مكرر.</div><div class="card"><div class="card-head"><div class="table-tools"><input class="search" id="bookSearch" placeholder="العنوان / المؤلف / ISBN"><select class="select" id="bookStatusFilter"><option value="">كل الحالات</option><option>متاح</option><option>مستعار</option><option>محجوز</option><option>مفقود</option><option>تالف</option><option>صيانة</option></select></div><span>${groups.length} عنوان • ${state.books.length} نسخة</span></div><div id="bookTableWrap">${catalogTableV06(groups)}</div></div>`}
function bindBookView(){const search=()=>{const q=$('#bookSearch').value.trim().toLowerCase(),st=$('#bookStatusFilter').value;let g=catalogGroupsV06();g=g.filter(x=>(!q||[x.title,x.author,x.isbn,x.category].join(' ').toLowerCase().includes(q))&&(!st||x.copies.some(c=>c.status===st)));$('#bookTableWrap').innerHTML=catalogTableV06(g)};$('#bookSearch').oninput=search;$('#bookStatusFilter').onchange=search;$('#addBookBtn').onclick=()=>openBookModal();$('#printAllBooks').onclick=printAllBookLabels;$('#bookTemplateBtn').onclick=()=>downloadStatic('templates/قالب_استيراد_الكتب.xlsx','قالب_استيراد_الكتب.xlsx');$('#bookImportFile').onchange=e=>importTabular(e.target.files?.[0],'books')}
function openCatalogRecordV06(id){const g=catalogGroupsV06().find(x=>x.id===id);if(!g)return;openModal('سجل الكتاب',g.title,`<div class="record-head"><div class="book-cover large"></div><div><h2>${esc(g.title)}</h2><p>${esc(g.author||'—')} • ${esc(g.category||'—')} • ${g.copies.length} نسخة</p></div><button class="btn primary" onclick="closeModal();openBookModal(null,'${esc(g.id)}')">+ إضافة نسخة</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>كود النسخة</th><th>الباركود</th><th>العهدة</th><th>RFID</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${g.copies.map(c=>`<tr><td>${esc(c.code)}</td><td>${esc(c.barcode||c.code)}</td><td>${esc(c.accession||'—')}</td><td>${c.rfidTag?'مرتبط':'—'}</td><td><span class="status ${statusClass(c.status)}">${esc(c.status)}</span></td><td><div class="row-actions"><button class="btn ghost btn-sm" onclick="printBookLabel('${esc(c.code)}')">ملصق</button><button class="btn secondary btn-sm" onclick="closeModal();openBookModal('${esc(c.code)}')">تعديل</button><button class="btn ghost btn-sm" onclick="closeModal();openCopyStatusModalV06('${esc(c.code)}')">الحالة</button></div></td></tr>`).join('')}</tbody></table></div><h4>سجل الاستعارة للعنوان</h4>${loanTable(state.loans.filter(l=>g.copies.some(c=>c.code===l.bookCode)))}`,true)}
function openBookModal(code=null,catalogId=null){const b=code?state.books.find(x=>x.code===code):null,g=!b&&catalogId?catalogGroupsV06().find(x=>x.id===catalogId):null;openModal(b?'تعديل نسخة كتاب':g?'إضافة نسخة للعنوان':'إضافة عنوان ونسخة','بيانات العنوان مشتركة بين النسخ، وبيانات النسخة فريدة.',`<input id="mBookCatalogId" type="hidden" value="${esc(b?.dbBookId||g?.dbBookId||'')}"><div class="modal-form"><div class="field full"><label>عنوان الكتاب *</label><input id="mBookTitle" value="${esc(b?.title||g?.title||'')}"></div><div class="field"><label>المؤلف</label><input id="mBookAuthor" value="${esc(b?.author||g?.author||'')}"></div><div class="field"><label>التصنيف</label><input id="mBookCategory" value="${esc(b?.category||g?.category||'')}"></div><div class="field"><label>الرف</label><input id="mBookShelf" value="${esc(b?.shelf||g?.shelf||'')}"></div><div class="field"><label>ISBN</label><input id="mBookIsbn" value="${esc(b?.isbn||g?.isbn||'')}"></div><div class="field"><label>الناشر</label><input id="mBookPublisher" value="${esc(b?.publisher||g?.publisher||'')}"></div><div class="field"><label>السنة</label><input id="mBookYear" value="${esc(b?.year||g?.year||'')}"></div><div class="field"><label>كود النسخة *</label><input id="mBookCode" value="${esc(b?.code||nextBookCode())}"></div><div class="field"><label>باركود رقمي *</label><input id="mBookBarcode" inputmode="numeric" value="${esc(b?.barcode||numericBarcodeV06('22'))}"></div><div class="field"><label>رقم العهدة</label><input id="mBookAccession" value="${esc(b?.accession||nextAccession())}"></div><div class="field"><label>RFID UID</label><input id="mBookRfid" value="${esc(b?.rfidTag||'')}"></div><div class="modal-actions full"><button class="btn ghost" onclick="closeModal()">إلغاء</button><button class="btn primary" id="saveBookModal">حفظ</button></div></div>`);$('#saveBookModal').onclick=()=>saveBookModal(code)}
async function saveBookModal(original){const title=$('#mBookTitle').value.trim(),author=$('#mBookAuthor').value.trim(),category=$('#mBookCategory').value.trim()||'غير مصنف',shelf=$('#mBookShelf').value.trim()||'—',code=$('#mBookCode').value.trim().toUpperCase(),barcode=$('#mBookBarcode').value.trim(),accession=$('#mBookAccession').value.trim(),isbn=$('#mBookIsbn').value.trim(),publisher=$('#mBookPublisher').value.trim(),year=$('#mBookYear').value.trim(),rfid=$('#mBookRfid').value.trim();if(!title||!code||!barcode){toast('العنوان وكود النسخة والباركود مطلوبة');return}const old=original?state.books.find(x=>x.code===original):null;if(state.books.some(x=>x.code===code&&x!==old)){toast('كود النسخة مستخدم');return}if(state.books.some(x=>x.barcode===barcode&&x!==old)){toast('الباركود مستخدم');return}if(rfid&&state.books.some(x=>x.rfidTag===rfid&&x!==old)){toast('RFID مرتبط بنسخة أخرى');return}
 if(remoteMode){let bookId=old?.dbBookId||$('#mBookCatalogId').value||'';if(!bookId){const match=state.books.find(x=>(isbn&&x.isbn===isbn)||(!isbn&&x.title.trim()===title&&String(x.author||'').trim()===author));bookId=match?.dbBookId||''}
   const catalog={school_id:CLOUD.schoolId,title,author:author||null,isbn:isbn||null,category,publisher:publisher||null,publication_year:year?Number(year):null,call_number:old?.callNumber||code,shelf,active:true};
   if(bookId){const {error}=await sb.from('books').update(catalog).eq('id',bookId);if(error){toast('تعذر تحديث بيانات الكتاب: '+error.message);return}}
   else{const {data,error}=await sb.from('books').insert(catalog).select('id').single();if(error){toast('تعذر إضافة الكتاب: '+error.message);return}bookId=data.id}
   const copy={school_id:CLOUD.schoolId,book_id:bookId,copy_code:code,accession_number:accession||null,barcode,rfid_uid:rfid||null};const resp=old?.dbCopyId?await sb.from('book_copies').update(copy).eq('id',old.dbCopyId):await sb.from('book_copies').insert({...copy,status:'available'});if(resp.error){toast('تعذر حفظ النسخة: '+resp.error.message);return}logActivity(old?'تعديل نسخة':'إضافة نسخة',title,{bookCode:code});await loadCloudState(false,true);closeModal();render('books');toast('تم حفظ الكتاب والنسخة');return}
 if(old)Object.assign(old,{title,author,category,shelf,code,barcode,accession,isbn,publisher,year,rfidTag:rfid});else state.books.push({code,barcode,title,author,category,shelf,accession,isbn,publisher,year,rfidTag:rfid,status:'متاح'});saveState(false);closeModal();render('books')}
function openCopyStatusModalV06(code){const b=state.books.find(x=>x.code===code);if(!b)return;if(['مستعار','محجوز'].includes(b.status)){toast('لا يمكن تغيير حالة نسخة مستعارة أو محجوزة');return}openModal('حالة النسخة',b.title,`<div class="form-stack"><div class="field"><label>الحالة</label><select id="copyStatusV06"><option value="متاح" ${b.status==='متاح'?'selected':''}>متاح</option><option value="مفقود" ${b.status==='مفقود'?'selected':''}>مفقود</option><option value="تالف" ${b.status==='تالف'?'selected':''}>تالف</option><option value="صيانة" ${b.status==='صيانة'||b.status==='موقوف'?'selected':''}>صيانة / موقوف</option></select></div><div class="modal-actions"><button class="btn ghost" onclick="closeModal()">إلغاء</button><button class="btn primary" id="saveCopyStatusV06">حفظ</button></div></div>`);$('#saveCopyStatusV06').onclick=async()=>{const status=$('#copyStatusV06').value;if(remoteMode&&b.dbCopyId){const {error}=await sb.from('book_copies').update({status:bookStatusDbV06(status)}).eq('id',b.dbCopyId);if(error){toast(error.message);return}await loadCloudState(false,true)}else{b.status=status;saveState(false)}closeModal();render('books');toast('تم تحديث حالة النسخة')}}
function topBooks(n=10){const map=new Map();for(const l of state.loans){const c=state.books.find(b=>b.code===l.bookCode);const key=c?.dbBookId||c?.title||l.book;const x=map.get(key)||{code:c?.code||l.bookCode,count:0,title:c?.title||l.book||l.bookCode};x.count++;map.set(key,x)}return [...map.values()].sort((a,b)=>b.count-a.count).slice(0,n)}
function openReservationModal(){const groups=catalogGroupsV06().filter(g=>g.copies.some(c=>!['مفقود','تالف','صيانة','موقوف'].includes(c.status)));openModal('حجز كتاب','الحجز يكون على عنوان الكتاب، والنظام يخصص النسخة المناسبة تلقائيًا.',`<div class="modal-form"><div class="field full"><label>الطالب</label><select id="resStudent">${state.students.filter(s=>s.status==='نشط').map(s=>`<option value="${esc(s.code)}">${esc(s.name)} — ${esc(s.code)}</option>`).join('')}</select></div><div class="field full"><label>الكتاب</label><select id="resBook">${groups.map(g=>`<option value="${esc(g.dbBookId||g.id)}">${esc(g.title)} — ${g.copies.length} نسخة</option>`).join('')}</select></div><div class="modal-actions full"><button class="btn ghost" onclick="closeModal()">إلغاء</button><button class="btn primary" id="saveReservationBtn">تأكيد الحجز</button></div></div>`);$('#saveReservationBtn').onclick=()=>createReservation($('#resStudent').value,$('#resBook').value)}
async function createReservation(studentCode,bookId){if(remoteMode){const res=await cloudTransaction('reserve',{studentCode,bookId});if(res?.ok){await loadCloudState(false,true);closeModal();render('reservations');toast(res.status==='ready'?'تم الحجز والنسخة جاهزة':'تمت إضافته لقائمة الانتظار')}else toast(res?.message||'تعذر الحجز');return}toast('الحجز المتقدم متاح في الوضع السحابي')}

function settings(){const c=state.config;return `<div class="section-title"><div><h2>إعدادات النظام</h2><p>الهوية والسياسات ومحطة الخدمة الذاتية والباركود والنسخ الاحتياطي.</p></div><button class="btn primary" id="saveSettingsBtn">حفظ التغييرات</button></div><div class="settings-grid"><div class="card"><div class="card-head"><h3>هوية النظام</h3><span>BRANDING</span></div><div class="brand-settings-preview"><div id="settingsLogoPreview" class="settings-logo">${c.logo?`<img src="${c.logo}">`:'م'}</div><div><b id="settingsPreviewName">${esc(c.siteName)}</b><span id="settingsPreviewSchool">${esc(c.schoolName)}</span></div></div><div class="form-stack"><div class="field"><label>اسم الموقع</label><input id="cfgSiteName" value="${esc(c.siteName)}"></div><div class="field"><label>اسم المدرسة</label><input id="cfgSchoolName" value="${esc(c.schoolName)}"></div><div class="field"><label>شعار المدرسة</label><input id="cfgLogo" type="file" accept="image/*"></div><button class="btn ghost" id="clearLogoBtn">إزالة الشعار</button></div></div><div class="card"><div class="card-head"><h3>سياسة الاستعارة</h3><span>POLICY</span></div><div class="form-grid"><div class="field"><label>أقصى عدد كتب</label><input id="cfgMaxBooks" type="number" min="1" value="${c.maxBooks}"></div><div class="field"><label>مدة الاستعارة بالأيام</label><input id="cfgLoanDays" type="number" min="1" value="${c.loanDays}"></div><div class="field"><label>عدد التجديدات</label><input id="cfgRenewals" type="number" min="0" value="${c.renewals}"></div><div class="field"><label>مدة صلاحية الحجز</label><input id="cfgReservationDays" type="number" min="1" value="${c.reservationDays}"></div></div><div class="switch-row"><div><b>منع الاستعارة عند وجود تأخير</b></div><div id="cfgPreventOverdue" class="toggle ${c.preventOverdue?'on':''}"></div></div><div class="switch-row"><div><b>إغلاق جلسة الطالب تلقائيًا</b></div><div id="cfgAutoClose" class="toggle ${c.autoClose?'on':''}"></div></div><div class="switch-row"><div><b>صوت نجاح العملية</b></div><div id="cfgSuccessSound" class="toggle ${c.successSound!==false?'on':''}"></div></div><div class="switch-row"><div><b>السماح بمسح الرقم الشخصي</b><div class="switch-help">غير مفضل للخصوصية؛ اتركه مغلقًا واستخدم الباركود الداخلي.</div></div><div id="cfgAllowPersonal" class="toggle ${c.allowPersonalIdScan?'on':''}"></div></div><div class="field"><label>مهلة الجلسة بالثواني</label><input id="cfgSessionSeconds" type="number" min="5" value="${c.sessionSeconds}"></div></div><div class="card"><div class="card-head"><h3>القارئ والمحطة</h3><span>HARDWARE</span></div><div class="form-stack"><div class="field"><label>المحطة الحالية على هذا الجهاز</label><select id="cfgStation">${state.stations.filter(x=>x.enabled).map(x=>`<option value="${esc(x.id)}" ${x.id===c.currentStationId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>وضع القارئ</label><select id="cfgReaderMode"><option value="barcode" ${c.readerMode==='barcode'?'selected':''}>Barcode</option><option value="rfid" ${c.readerMode==='rfid'?'selected':''}>RFID</option><option value="hybrid" ${c.readerMode==='hybrid'?'selected':''}>Barcode + RFID</option></select></div><button class="btn secondary" id="scannerTestBtn">اختبار قارئ الباركود / RFID</button><div class="info-banner compact"><b>أفضل إعداد:</b> اجعل قارئ الباركود يرسل Enter بعد القراءة. الباركودات الجديدة رقمية لتجنب اختلاف لغة لوحة المفاتيح.</div></div></div><div class="card"><div class="card-head"><h3>حماية وضع Kiosk</h3><span>SECURITY</span></div><p class="muted-text">يمكنك تعيين رمز PIN لمنع الطلاب من الخروج من وضع المحطة. إذا لم يتم تعيين رمز، فزر العودة سيُسجّل خروج حساب المحطة ويعيد شاشة تسجيل الدخول فقط.</p><div class="field"><label>رمز الخروج الجديد (4–8 أرقام)</label><input id="cfgExitPin" type="password" inputmode="numeric" maxlength="8" placeholder="مثال: 2580"></div><div class="backup-actions"><button class="btn secondary" id="saveExitPinBtn">تعيين / تغيير رمز الخروج</button><button class="btn ghost" id="clearExitPinBtnV061">إلغاء رمز الخروج</button></div></div><div class="card"><div class="card-head"><h3>النسخ الاحتياطي</h3><span>DATA</span></div><p class="muted-text">التصدير يشمل بيانات التشغيل الحالية. كلمات مرور Supabase Auth لا تدخل في ملف النسخة الاحتياطية.</p><div class="backup-actions"><button class="btn secondary" id="exportBackupBtn">تصدير JSON</button><label class="btn ghost file-btn">استعادة بيانات أساسية<input id="importBackupFile" type="file" accept=".json" hidden></label></div><div class="sync-status">${remoteMode?'✓ متصل بـ Supabase Cloud':'غير متصل بالسحابة'}</div></div></div>`}
function bindSettings(){const preview=()=>{$('#settingsPreviewName').textContent=$('#cfgSiteName').value||'اسم النظام';$('#settingsPreviewSchool').textContent=$('#cfgSchoolName').value||'اسم المدرسة'};$('#cfgSiteName').oninput=preview;$('#cfgSchoolName').oninput=preview;$('#cfgLogo').onchange=e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>1500000){toast('الشعار كبير؛ استخدم ملفًا أقل من 1.5MB');return}const r=new FileReader();r.onload=()=>{pendingLogoData=r.result;$('#settingsLogoPreview').innerHTML=`<img src="${pendingLogoData}">`};r.readAsDataURL(f)};$('#clearLogoBtn').onclick=()=>{pendingLogoData='';$('#settingsLogoPreview').textContent='م'};['#cfgPreventOverdue','#cfgAutoClose','#cfgSuccessSound','#cfgAllowPersonal'].forEach(id=>$(id).onclick=()=>$(id).classList.toggle('on'));$('#saveSettingsBtn').onclick=saveSettings;$('#scannerTestBtn').onclick=openScannerTestV06;$('#saveExitPinBtn').onclick=saveExitPinV06;$('#clearExitPinBtnV061').onclick=clearExitPinV061;$('#exportBackupBtn').onclick=exportBackup;$('#importBackupFile').onchange=e=>importBackup(e.target.files?.[0])}
async function saveSettings(){const c=state.config;c.siteName=$('#cfgSiteName').value.trim()||defaults.config.siteName;c.schoolName=$('#cfgSchoolName').value.trim()||defaults.config.schoolName;c.logo=pendingLogoData;c.maxBooks=Math.max(1,Number($('#cfgMaxBooks').value)||3);c.loanDays=Math.max(1,Number($('#cfgLoanDays').value)||14);c.renewals=Math.max(0,Number($('#cfgRenewals').value)||0);c.reservationDays=Math.max(1,Number($('#cfgReservationDays').value)||3);c.preventOverdue=$('#cfgPreventOverdue').classList.contains('on');c.autoClose=$('#cfgAutoClose').classList.contains('on');c.successSound=$('#cfgSuccessSound').classList.contains('on');c.allowPersonalIdScan=$('#cfgAllowPersonal').classList.contains('on');c.sessionSeconds=Math.max(5,Number($('#cfgSessionSeconds').value)||10);c.currentStationId=$('#cfgStation').value;c.readerMode=$('#cfgReaderMode').value;if(remoteMode){const a=await sb.from('schools').update({name:c.schoolName,site_name:c.siteName,logo_url:c.logo||null}).eq('id',CLOUD.schoolId),b=await sb.from('library_settings').update({loan_days:c.loanDays,max_books:c.maxBooks,max_renewals:c.renewals,block_if_overdue:c.preventOverdue,session_timeout_seconds:c.sessionSeconds,reservation_hold_days:c.reservationDays,success_sound:c.successSound,allow_personal_id_scan:c.allowPersonalIdScan}).eq('school_id',CLOUD.schoolId);if(a.error||b.error){toast('تعذر حفظ بعض الإعدادات');return}}persistLocal();applyBranding();render('settings');toast('تم حفظ الإعدادات')}
async function saveExitPinV06(){const pin=$('#cfgExitPin').value.trim();if(!/^\d{4,8}$/.test(pin)){toast('الرمز يجب أن يكون من 4 إلى 8 أرقام');return}const {data,error}=await sb.functions.invoke('library-users',{body:{action:'set_exit_pin',schoolId:CLOUD.schoolId,pin}});if(error||!data?.ok){toast(data?.message||'تعذر حفظ الرمز');return}$('#cfgExitPin').value='';toast('تم تعيين رمز خروج المحطة')}
async function clearExitPinV061(){openModal('إلغاء رمز خروج المحطة','بعد الإلغاء سيتمكن زر العودة من تسجيل خروج حساب المحطة والعودة إلى شاشة الدخول دون طلب PIN.',`<div class="modal-actions"><button class="btn ghost" id="cancelClearPinV061">إلغاء</button><button class="btn danger" id="confirmClearPinV061">إلغاء رمز الخروج</button></div>`);$('#cancelClearPinV061').onclick=closeModal;$('#confirmClearPinV061').onclick=async()=>{const {error}=await sb.from('library_settings').update({kiosk_exit_pin_hash:null}).eq('school_id',CLOUD.schoolId);if(error){toast('تعذر إلغاء رمز الخروج');return}closeModal();toast('تم إلغاء رمز خروج المحطة')}}
function openScannerTestV06(){openModal('اختبار القارئ','امسح بطاقة أو كتابًا الآن. لن يتم تنفيذ استعارة أو إرجاع.',`<div class="scanner-test"><input id="scannerTestInput" class="big-scan" placeholder="امسح هنا ثم Enter" autofocus><div id="scannerTestResult" class="scan-test-result">في انتظار القراءة…</div><p class="muted-text">يعرض الاختبار القيمة الخام كما وصلت من القارئ، وطولها ووقت القراءة.</p></div>`);const i=$('#scannerTestInput'),r=$('#scannerTestResult');let started=performance.now();i.oninput=()=>{if(i.value.length===1)started=performance.now()};i.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const v=i.value.trim();if(!v)return;const ms=Math.round(performance.now()-started);r.innerHTML=`<b>✓ القراءة ناجحة</b><br>الكود: <code>${esc(v)}</code><br>الطول: ${v.length} محرف/رقم<br>الزمن التقريبي: ${ms}ms`;i.value='';playSuccessSoundV06();started=performance.now()}};setTimeout(()=>i.focus(),50)}

function studentCardHTML(s){const val=s.barcode||s.code;return `<div class="student-card-print"><div><div class="top">${state.config.logo?`<img class="plogo" src="${state.config.logo}">`:'<div class="mark">م</div>'}<div><b>${esc(state.config.schoolName)}</b><div class="school">${esc(state.config.siteName)}</div></div></div><div class="name">${esc(s.name)}</div><div class="meta">الصف: ${esc(s.grade)} — الشعبة: ${esc(s.section)} — الكود: ${esc(s.code)}</div></div><div><div class="barcode">${barcodeSVG(val)}</div><div class="code">${esc(val)}</div></div></div>`}
function bookLabelHTML(b){const val=b.barcode||b.code;return `<div class="book-label"><div class="top">${state.config.logo?`<img class="plogo" src="${state.config.logo}">`:'<div class="mark">م</div>'}<div><b>${esc(state.config.schoolName)}</b><div class="small">${esc(state.config.siteName)}</div></div></div><div class="name">${esc(b.title)}</div><div class="small">${esc(b.category)} • الرف ${esc(b.shelf)} • ${esc(b.accession||'')} • ${esc(b.code)}</div><div class="barcode">${barcodeSVG(val,50)}</div><div class="code">${esc(val)}</div></div>`}

async function fetchAllV06(makeQuery,max=20000){const out=[];for(let from=0;from<max;from+=1000){const {data,error}=await makeQuery(from,from+999);if(error)throw error;out.push(...(data||[]));if(!data||data.length<1000)break}return out}
function mapCloudSnapshotV06(students,books,copies,loans,reservations,activity=[]){const sm=new Map(students.map(x=>[x.id,x])),bm=new Map(books.map(x=>[x.id,x])),cm=new Map(copies.map(x=>[x.id,x]));state.students=students.map(x=>({dbId:x.id,code:x.student_code,barcode:x.barcode||x.student_code,personalId:x.personal_number||'',name:x.full_name,grade:x.grade||'',section:x.section||'',status:x.active?'نشط':'موقوف',rfidTag:x.rfid_uid||''}));state.books=copies.map(c=>{const b=bm.get(c.book_id)||{};return {dbBookId:c.book_id,dbCopyId:c.id,code:c.copy_code,barcode:c.barcode||c.copy_code,accession:c.accession_number||'',isbn:b.isbn||'',title:b.title||'كتاب',author:b.author||'',category:b.category||'غير مصنف',publisher:b.publisher||'',year:b.publication_year||'',shelf:b.shelf||'',status:bookStatusArV06(c.status),rfidTag:c.rfid_uid||'',callNumber:b.call_number||''}});state.loans=(loans||[]).map(l=>({id:l.loan_id,studentCode:l.student_code,student:l.student_name,bookCode:l.copy_code,book:l.title,loanDateISO:(l.loaned_at||'').slice(0,10),dueDateISO:(l.due_at||'').slice(0,10),returnedDateISO:l.returned_at?(l.returned_at||'').slice(0,10):null,returnedISO:l.returned_at||null,status:l.returned_at?'تم الإرجاع':(new Date(l.due_at)<new Date()?'متأخر':'مستعار'),renewalsUsed:l.renewal_count||0,stationId:(state.stations.find(s=>s.name===l.checkout_station_name)?.id)||'',checkoutStationName:l.checkout_station_name||'',returnStationName:l.return_station_name||'',createdISO:l.loaned_at}));state.reservations=(reservations||[]).map(r=>{const stu=sm.get(r.student_id),book=bm.get(r.book_id),ready=cm.get(r.ready_copy_id),first=copies.find(c=>c.book_id===r.book_id);return {id:r.id,studentCode:stu?.student_code||'',bookCode:ready?.copy_code||first?.copy_code||'',dbBookId:r.book_id,status:['queued','ready'].includes(r.status)?'نشط':r.status==='fulfilled'?'مكتمل':r.status==='cancelled'?'ملغي':'منتهي',createdISO:r.requested_at,expiresISO:r.expires_at,ready:r.status==='ready',bookTitle:book?.title||''}});state.activityLogs=(activity||[]).map(x=>({id:x.id,type:x.action,message:x.details?.message||x.action,meta:x.details||{},stationId:state.stations.find(s=>s.dbId===x.station_id)?.id||'',user:x.details?.actor_name||'—',atISO:x.created_at}));}
async function loadCloudState(showError=true,preserveKiosk=false){
 try{const {data:{user}}=await sb.auth.getUser();if(!user)return false;authUser=user;const {data:mem,error:me}=await sb.from('memberships').select('user_id,school_id,full_name,role,active,station_id').eq('user_id',user.id).eq('school_id',CLOUD.schoolId).maybeSingle();if(me||!mem?.active)return false;currentUser={id:user.id,username:user.email||'',displayName:mem.full_name,role:mem.role,active:true,stationDbId:mem.station_id||null};const kioskState=preserveKiosk?state.kiosk:{step:'student',student:null,lastBook:null,lastLoanDueISO:null};
   if(mem.role==='viewer'){const vr=await cloudTransaction('viewer_snapshot');if(!vr?.ok)throw new Error(vr?.message||'viewer snapshot failed');const s=vr.snapshot,school=s.school,settings=s.settings;state.config={...state.config,siteName:school?.site_name||'Bilal Smart Library',schoolName:school?.name||'',logo:school?.logo_url||'',maxBooks:settings?.max_books||3,loanDays:settings?.loan_days||14,renewals:settings?.max_renewals??1,preventOverdue:settings?.block_if_overdue??true,reservationDays:settings?.reservation_hold_days||3,sessionSeconds:settings?.session_timeout_seconds||12,successSound:settings?.success_sound??true};state.stations=(s.stations||[]).map(x=>({dbId:x.id,id:x.station_code,name:x.name,location:x.location||'',type:x.station_type||'self_checkout',readerMode:x.scanner_mode||'hybrid',enabled:x.active,lastSeen:x.last_seen_at,externalActive:!!x.public_token_created_at,publicTokenCreatedAt:x.public_token_created_at||null}));mapCloudSnapshotV06(s.students||[],s.books||[],s.copies||[],s.loans||[],s.reservations||[],[]);state.kiosk=kioskState;applyBranding();persistLocal();remoteMode=true;return true}
   const [{data:school,error:se},{data:settings,error:sete},{data:stations,error:ste}]=await Promise.all([sb.from('schools').select('*').eq('id',CLOUD.schoolId).single(),sb.from('library_settings').select('*').eq('school_id',CLOUD.schoolId).single(),sb.from('stations').select('*').eq('school_id',CLOUD.schoolId).order('created_at')]);if(se||sete||ste)throw(se||sete||ste);state.config={...state.config,siteName:school?.site_name||'Bilal Smart Library',schoolName:school?.name||'مدرسة بلال بن رباح النموذجية للبنين',logo:school?.logo_url||'',maxBooks:settings?.max_books||3,loanDays:settings?.loan_days||14,renewals:settings?.max_renewals??1,preventOverdue:settings?.block_if_overdue??true,reservationDays:settings?.reservation_hold_days||3,autoClose:true,sessionSeconds:settings?.session_timeout_seconds||12,successSound:settings?.success_sound??true,allowPersonalIdScan:settings?.allow_personal_id_scan??false};state.stations=(stations||[]).map(x=>({dbId:x.id,id:x.station_code,name:x.name,location:x.location||'',type:x.station_type||'self_checkout',readerMode:x.scanner_mode||'hybrid',enabled:x.active,lastSeen:x.last_seen_at,externalActive:!!x.public_token_created_at,publicTokenCreatedAt:x.public_token_created_at||null}));if(!state.stations.length)state.stations=deepClone(defaults.stations);if(mem.role==='kiosk'){const assigned=state.stations.find(x=>x.dbId===mem.station_id);if(assigned)state.config.currentStationId=assigned.id;state.students=[];state.books=[];state.loans=[];state.reservations=[];state.activityLogs=[];state.kiosk=kioskState;state.users=[{...currentUser,stationCode:assigned?.id||'',stationName:assigned?.name||''}];applyBranding();persistLocal();remoteMode=true;cloudLastLoad=Date.now();return true}
   if(!state.stations.some(x=>x.id===state.config.currentStationId))state.config.currentStationId=state.stations[0]?.id||'KIOSK-01';
   const [students,books,copies,loans,reservations,activityRows]=await Promise.all([fetchAllV06((f,t)=>sb.from('students').select('*').eq('school_id',CLOUD.schoolId).order('full_name').range(f,t)),fetchAllV06((f,t)=>sb.from('books').select('*').eq('school_id',CLOUD.schoolId).range(f,t)),fetchAllV06((f,t)=>sb.from('book_copies').select('*').eq('school_id',CLOUD.schoolId).range(f,t)),fetchAllV06((f,t)=>sb.from('loan_details').select('*').eq('school_id',CLOUD.schoolId).order('loaned_at',{ascending:false}).range(f,t),10000),fetchAllV06((f,t)=>sb.from('reservations').select('*').eq('school_id',CLOUD.schoolId).order('requested_at',{ascending:false}).range(f,t),10000),sb.from('activity_logs').select('*').eq('school_id',CLOUD.schoolId).order('created_at',{ascending:false}).limit(1000).then(r=>{if(r.error)throw r.error;return r.data||[]})]);mapCloudSnapshotV06(students,books,copies,loans,reservations,activityRows);state.kiosk=kioskState;await loadCloudUsers();refreshDerivedState();persistLocal();applyBranding();remoteMode=true;cloudLastLoad=Date.now();return true;
 }catch(e){console.error('cloud load v06',e);if(showError)toast('تعذر تحميل البيانات السحابية');return false}
}
function scheduleRealtimeReloadV06(){clearTimeout(realtimeDebounceV06);realtimeDebounceV06=setTimeout(async()=>{if(document.hidden||document.querySelector('#modalBackdrop:not(.hidden)')||state.kiosk?.student)return;const v=currentView;if(await loadCloudState(false,true)){if(!$('#appView').classList.contains('hidden'))render(v)}},900)}
function startRemotePolling(){clearInterval(remotePoller);clearInterval(heartbeatTimerV06);try{if(realtimeChannelV06)sb.removeChannel(realtimeChannelV06)}catch{};realtimeChannelV06=sb.channel('bilal-library-v06');for(const table of ['students','books','book_copies','loans','reservations','stations'])realtimeChannelV06.on('postgres_changes',{event:'*',schema:'public',table,filter:`school_id=eq.${CLOUD.schoolId}`},scheduleRealtimeReloadV06);realtimeChannelV06.subscribe();heartbeatTimerV06=setInterval(()=>cloudTransaction('heartbeat',{stationCode:currentStation().id}),30000);cloudTransaction('heartbeat',{stationCode:currentStation().id});remotePoller=setInterval(()=>{if(!document.hidden&&!state.kiosk?.student)scheduleRealtimeReloadV06()},60000)}
async function detectRemote(){const {data}=await sb.auth.getSession();if(!data.session){remoteMode=false;return false}authUser=data.session.user;const ok=await loadCloudState(false,true);remoteMode=ok;if(ok)startRemotePolling();return ok}

async function cloudImportStudents(items,fileName='import.xlsx'){const valid=items.map((x,i)=>({...x,barcode:x.barcode||numericBarcodeV06('21')}));let imported=0;const {data:batch}=await sb.from('import_batches').insert({school_id:CLOUD.schoolId,import_type:'students',file_name:fileName,total_rows:valid.length,imported_rows:0,skipped_rows:0,errors:[],created_by:authUser?.id||null}).select('id').maybeSingle();for(let i=0;i<valid.length;i+=200){const part=valid.slice(i,i+200).map(x=>({school_id:CLOUD.schoolId,student_code:x.code,personal_number:x.personalId||null,full_name:x.name,grade:x.grade||null,section:x.section||null,barcode:x.barcode,rfid_uid:x.rfidTag||null,active:true}));const {error}=await sb.from('students').upsert(part,{onConflict:'school_id,student_code'});if(error){toast('تعذر استيراد دفعة طلاب: '+error.message);return false}imported+=part.length;$('#importProgressText')&&($('#importProgressText').textContent=`${imported}/${valid.length}`);if(batch?.id)await sb.from('import_batches').update({imported_rows:imported}).eq('id',batch.id)}return true}
async function cloudImportBooks(items,fileName='import.xlsx'){try{let imported=0;const {data:batch}=await sb.from('import_batches').insert({school_id:CLOUD.schoolId,import_type:'books',file_name:fileName,total_rows:items.length,imported_rows:0,skipped_rows:0,errors:[],created_by:authUser?.id||null}).select('id').maybeSingle();const groups=new Map();for(const x of items){const key=x.isbn?`isbn:${x.isbn}`:`title:${x.title.trim().toLowerCase()}|${String(x.author||'').trim().toLowerCase()}`;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(x)}for(const group of groups.values()){const first=group[0];let existing=state.books.find(b=>(first.isbn&&b.isbn===first.isbn)||(!first.isbn&&b.title.trim()===first.title.trim()&&String(b.author||'').trim()===String(first.author||'').trim()));let bookId=existing?.dbBookId;if(!bookId){const {data,error}=await sb.from('books').insert({school_id:CLOUD.schoolId,title:first.title,author:first.author||null,isbn:first.isbn||null,category:first.category||null,publisher:first.publisher||null,publication_year:first.year?Number(first.year):null,call_number:first.code,shelf:first.shelf||null,active:true}).select('id').single();if(error)throw error;bookId=data.id}const rows=group.map(x=>({school_id:CLOUD.schoolId,book_id:bookId,copy_code:x.code,accession_number:x.accession||null,barcode:x.barcode||numericBarcodeV06('22'),rfid_uid:x.rfidTag||null,status:'available'}));for(let i=0;i<rows.length;i+=200){const {error}=await sb.from('book_copies').insert(rows.slice(i,i+200));if(error)throw error;imported+=Math.min(200,rows.length-i);$('#importProgressText')&&($('#importProgressText').textContent=`${imported}/${items.length}`);if(batch?.id)await sb.from('import_batches').update({imported_rows:imported}).eq('id',batch.id)}}return true}catch(e){console.error(e);toast('تعذر استيراد الكتب: '+e.message);return false}}
function showImportPreview(items,type){const ok=items.filter(x=>!x.errors.length),bad=items.filter(x=>x.errors.length);openModal('معاينة الاستيراد',`${ok.length} صف صالح • ${bad.length} صف به مشكلة`,`<div class="import-summary"><div><b>${items.length}</b><span>إجمالي الصفوف</span></div><div class="good"><b>${ok.length}</b><span>جاهز للاستيراد</span></div><div class="bad"><b>${bad.length}</b><span>يحتاج مراجعة</span></div></div><div class="table-scroll import-preview"><table class="data-table"><thead><tr><th>الصف</th><th>${type==='students'?'الاسم':'العنوان'}</th><th>الكود</th><th>الحالة</th></tr></thead><tbody>${items.slice(0,50).map(x=>`<tr><td>${x.row}</td><td>${esc(type==='students'?x.data.name:x.data.title)}</td><td>${esc(x.data.code)}</td><td>${x.errors.length?`<span class="status overdue">${esc(x.errors.join('، '))}</span>`:'<span class="status available">جاهز</span>'}</td></tr>`).join('')}</tbody></table></div><div class="import-progress"><b>التقدم:</b> <span id="importProgressText">0/${ok.length}</span></div><div class="modal-actions"><button class="btn ghost" onclick="closeModal()">إلغاء</button><button class="btn primary" id="confirmImportBtn" ${ok.length?'':'disabled'}>استيراد ${ok.length} سجل</button></div>`,true);$('#confirmImportBtn')?.addEventListener('click',async()=>{$('#confirmImportBtn').disabled=true;const data=ok.map(x=>x.data);const done=remoteMode?(type==='students'?await cloudImportStudents(data):await cloudImportBooks(data)):true;if(!done){$('#confirmImportBtn').disabled=false;return}if(!remoteMode){if(type==='students')state.students.push(...data);else state.books.push(...data);saveState(false)}else await loadCloudState(false,true);closeModal();render(type);toast(`تم استيراد ${ok.length} سجل بنجاح`)})}

async function exportBackup(){if(!remoteMode){downloadBlob(`bilal-smart-library-v06-backup-${todayISO()}.json`,JSON.stringify({version:VERSION,exportedAt:nowISO(),...serializableState()},null,2),'application/json');return}try{const [students,books,copies,loans,reservations,stations,settings,school]=await Promise.all([fetchAllV06((f,t)=>sb.from('students').select('*').eq('school_id',CLOUD.schoolId).range(f,t)),fetchAllV06((f,t)=>sb.from('books').select('*').eq('school_id',CLOUD.schoolId).range(f,t)),fetchAllV06((f,t)=>sb.from('book_copies').select('*').eq('school_id',CLOUD.schoolId).range(f,t)),fetchAllV06((f,t)=>sb.from('loans').select('*').eq('school_id',CLOUD.schoolId).range(f,t),10000),fetchAllV06((f,t)=>sb.from('reservations').select('*').eq('school_id',CLOUD.schoolId).range(f,t),10000),fetchAllV06((f,t)=>sb.from('stations').select('*').eq('school_id',CLOUD.schoolId).range(f,t)),sb.from('library_settings').select('*').eq('school_id',CLOUD.schoolId).single().then(r=>r.data),sb.from('schools').select('*').eq('id',CLOUD.schoolId).single().then(r=>r.data)]);downloadBlob(`bilal-smart-library-v06-cloud-backup-${todayISO()}.json`,JSON.stringify({version:VERSION,exportedAt:nowISO(),scope:'cloud-business-data',school,settings,stations,students,books,copies,loans,reservations,note:'Auth passwords are intentionally excluded.'},null,2),'application/json')}catch(e){toast('تعذر إنشاء النسخة الاحتياطية')}}
function importBackup(file){if(!file)return;const r=new FileReader();r.onload=async()=>{try{const x=JSON.parse(r.result);if(remoteMode){if(!Array.isArray(x.students)||!Array.isArray(x.books)||!Array.isArray(x.copies))throw new Error('الملف ليس نسخة سحابية متوافقة');if(!confirm('سيتم استيراد البيانات الأساسية (الطلاب والكتب والنسخ والمحطات والإعدادات) بدون كلمات المرور وبدون حذف البيانات الحالية. متابعة؟'))return;const students=x.students.map(s=>({...s,school_id:CLOUD.schoolId}));for(let i=0;i<students.length;i+=200){const {error}=await sb.from('students').upsert(students.slice(i,i+200),{onConflict:'id'});if(error)throw error}for(const b of x.books){const {error}=await sb.from('books').upsert({...b,school_id:CLOUD.schoolId},{onConflict:'id'});if(error)throw error}for(const c of x.copies){const {error}=await sb.from('book_copies').upsert({...c,school_id:CLOUD.schoolId},{onConflict:'id'});if(error)throw error}await loadCloudState(false,true);render('settings');toast('تمت استعادة البيانات الأساسية. الاستعارات التاريخية وكلمات المرور لم تُستبدل.');return}if(!Array.isArray(x.students)||!Array.isArray(x.books))throw new Error();replaceState(x);render('settings');toast('تمت الاستعادة')}catch(e){console.error(e);toast('ملف النسخة الاحتياطية غير صالح أو تعذر الاستيراد')}};r.readAsText(file,'utf-8')}

function bindDynamic(view){detachGlobalScanner();clearKioskTimer();if(view==='kiosk'){const inp=$('#kioskScan');inp?.focus();attachGlobalScanner(inp,handleScan);$('#finishSession')?.addEventListener('click',resetKiosk);if(state.kiosk.student)startKioskTimer()}if(view==='returns'){const inp=$('#returnScan');inp?.focus();attachGlobalScanner(inp,code=>returnBook(code,true))}if(view==='students')bindStudentView();if(view==='books')bindBookView();if(view==='loans')bindLoanView();if(view==='circulation')bindCirculationView();if(view==='overdue')$('#exportOverdueBtn')?.addEventListener('click',()=>exportLoansCSV(overdueLoans(),'overdue'));if(view==='reservations')$('#addReservationBtn')?.addEventListener('click',()=>openReservationModal());if(view==='reports')bindReports();if(view==='users'){$('#addStaffUserBtn')?.addEventListener('click',()=>openUserModal(null,'librarian'));$('#addKioskUserBtn')?.addEventListener('click',()=>openUserModal(null,'kiosk'))}if(view==='stations')$('#addStationBtn')?.addEventListener('click',()=>openStationModal());if(view==='activity')$('#exportActivityBtn')?.addEventListener('click',exportActivityCSV);if(view==='settings')bindSettings()}
