// v0.6 import aliases: keep internal codes separate from numeric HID-safe barcodes.
function mapStudentRows(rows){
  const h=rows[0],idx={
    name:findCol(h,['اسم الطالب','الاسم','student name','name']),
    personalId:findCol(h,['الرقم الشخصي','رقم شخصي','personal id','qid','student id']),
    grade:findCol(h,['الصف','grade','class']),
    section:findCol(h,['الشعبة','الفصل','section']),
    code:findCol(h,['كود الطالب','الكود','student code','code']),
    barcode:findCol(h,['باركود رقمي','باركود الطالب','barcode','student barcode']),
    rfidTag:findCol(h,['rfid','rfid uid','كود rfid'])
  };
  if(idx.name<0)throw new Error('لم أجد عمود اسم الطالب');
  let seq=0;
  const items=rows.slice(1).filter(r=>r.some(v=>String(v||'').trim())).map((r,i)=>{
    let code=idx.code>=0?String(r[idx.code]||'').trim().toUpperCase():'';
    if(!code){seq++;code=nextAvailableStudentCode(seq)}
    return {row:i+2,data:{
      code,
      barcode:idx.barcode>=0?String(r[idx.barcode]||'').trim():'',
      name:String(r[idx.name]||'').trim(),
      personalId:idx.personalId>=0?String(r[idx.personalId]||'').trim():'',
      grade:idx.grade>=0?String(r[idx.grade]||'').trim():'',
      section:idx.section>=0?String(r[idx.section]||'').trim():'',
      rfidTag:idx.rfidTag>=0?String(r[idx.rfidTag]||'').trim():'',
      status:'نشط'
    },errors:[]}
  }).map(x=>validateImportStudent(x));
  markInternalDuplicates(items,['code','barcode','personalId','rfidTag']);
  return items
}
function mapBookRows(rows){
  const h=rows[0],idx={
    title:findCol(h,['عنوان الكتاب','اسم الكتاب','العنوان','title','book title']),
    author:findCol(h,['المؤلف','author']),
    category:findCol(h,['التصنيف','category','classification']),
    shelf:findCol(h,['الرف','shelf']),
    code:findCol(h,['كود النسخة','كود الكتاب','book code','copy code','code']),
    barcode:findCol(h,['باركود رقمي','باركود النسخة','barcode','book barcode']),
    accession:findCol(h,['رقم العهدة','العهدة','accession','accession number']),
    isbn:findCol(h,['isbn','ردمك']),
    publisher:findCol(h,['الناشر','publisher']),
    year:findCol(h,['سنة النشر','السنة','publication year','year']),
    rfidTag:findCol(h,['rfid','rfid uid','كود rfid'])
  };
  if(idx.title<0)throw new Error('لم أجد عمود عنوان الكتاب');
  let seq=0;
  const items=rows.slice(1).filter(r=>r.some(v=>String(v||'').trim())).map((r,i)=>{
    let code=idx.code>=0?String(r[idx.code]||'').trim().toUpperCase():'';
    if(!code){seq++;code=nextAvailableBookCode(seq)}
    return {row:i+2,data:{
      code,
      barcode:idx.barcode>=0?String(r[idx.barcode]||'').trim():'',
      title:String(r[idx.title]||'').trim(),
      author:idx.author>=0?String(r[idx.author]||'').trim():'',
      category:idx.category>=0?String(r[idx.category]||'').trim():'',
      shelf:idx.shelf>=0?String(r[idx.shelf]||'').trim():'',
      accession:idx.accession>=0?String(r[idx.accession]||'').trim():'',
      isbn:idx.isbn>=0?String(r[idx.isbn]||'').trim():'',
      publisher:idx.publisher>=0?String(r[idx.publisher]||'').trim():'',
      publicationYear:idx.year>=0?String(r[idx.year]||'').trim():'',
      rfidTag:idx.rfidTag>=0?String(r[idx.rfidTag]||'').trim():'',
      status:'متاح'
    },errors:[]}
  }).map(x=>validateImportBook(x));
  markInternalDuplicates(items,['code','barcode','accession','rfidTag']);
  return items
}


